/* Finot Académie — Arts plastiques au collège, année scolaire 2026-2027 : 24 chapitres reconstruits (arts6a…arts3f).
   Programme d'enseignement des arts plastiques du cycle 3 et du cycle 4, arrêté du 9 novembre 2015 modifié par l'arrêté du
   17 juillet 2020 (NOR MENE2018714A), BO n°31 du 30 juillet 2020. Trois grandes questions structurent le programme : la
   représentation ; les fabrications et la relation entre l'objet et l'espace ; la matérialité de l'œuvre, l'objet et l'œuvre.
   Ce qui ne se vérifie pas à l'écran (la pratique plastique elle-même) n'est pas évalué par un générateur : chaque chapitre
   comporte une partie « 🎨 Atelier hors écran » (objectif, consigne, durée, matériel, sécurité, auto-évaluation), conformément
   au guide de rédaction ; les questions portent sur le vocabulaire, les notions, les démarches et la culture artistique
   (références croisées avec les chapitres d'histoire des arts, data/college/hda.js).
   Référence complémentaire : Éduscol — ressources d'accompagnement du programme d'arts plastiques. */
(function(){
'use strict';
const MQ=window.MQCollege;if(!MQ)return;const H=MQ.H;
const {R,P,ch,num,txt,order,tf,bank,pairs,sort,seq,mix,pickN,shuffle,nf}=H;
const C=(d,u,ex,m,a,r)=>({d,u,ex,m,a,r});const T=(t,h)=>({t,h});
const BO='Programme d’arts plastiques des cycles 3 et 4 — arrêté du 17 juillet 2020 (NOR MENE2018714A), BO n°31 du 30 juillet 2020';
const EDU='Éduscol — ressources d’accompagnement du programme d’arts plastiques';
const HE=(obj,cons,duree,mat,sec,auto)=>T('🎨 Atelier hors écran',`<p><b>Objectif :</b> ${obj}</p><p><b>Consigne :</b> ${cons}</p><p><b>Durée :</b> ${duree}</p><p><b>Matériel :</b> ${mat}</p><p><b>Sécurité :</b> ${sec}</p><p><b>Auto-évaluation :</b> ${auto}</p>`);

MQ.add('arts','6',[
{id:'arts6a',name:'Observer, décrire et expérimenter les formes',icon:'⭐',domain:'Pratique artistique',
 refs:[BO,EDU],
 tip:'Une forme géométrique (cercle, carré, triangle) obéit à des règles précises ; une forme organique (comme une feuille ou un nuage) a des contours irréguliers et vivants.',
 c:C(`Avant de créer, on apprend à <b>observer</b> et à nommer les formes qui nous entourent : <b>géométriques</b> (régulières) ou <b>organiques</b> (irrégulières, inspirées du vivant).`,
  [T('Formes géométriques et organiques',`<p>Une forme <b>géométrique</b> (cercle, carré, triangle, rectangle) suit des règles précises et peut se décrire avec des mots mathématiques. Une forme <b>organique</b> a des contours irréguliers, souples, qui rappellent des formes naturelles (feuilles, nuages, galets). Un même dessin peut combiner les deux types.</p>`),
   T('Format, cadrage et support',`<p>Le <b>format</b> d’une œuvre est sa taille et sa proportion (carré, rectangle allongé, très grand ou très petit) : il influence la perception de l’œuvre. Le <b>cadrage</b> désigne ce qui est inclus ou exclu de la représentation. Le <b>support</b> est la surface sur laquelle on travaille (papier, toile, bois, mur) ; il influence aussi le résultat final.</p>`),
   HE('Réaliser une composition combinant formes géométriques et formes organiques.','Sur une feuille, dessiner ou coller au moins 3 formes géométriques et 3 formes organiques, en variant leurs tailles.','30 minutes.','Papier, crayons ou feutres, éventuellement des papiers de couleur et de la colle.','Utiliser des ciseaux avec précaution si découpage de papier.','Ai-je utilisé des formes géométriques ET des formes organiques ? Ai-je varié leurs tailles ?')],
  [{q:'Observe un dessin représentant un soleil (cercle) entouré de feuillages (formes irrégulières).',s:['Le soleil est une forme géométrique (cercle).','Les feuillages sont des formes organiques (contours irréguliers).','La composition combine les deux types de formes.']}],
  ['Je distingue forme géométrique et forme organique.','Je sais ce qu’est le format d’une œuvre.','Je comprends ce que signifie le cadrage.','Je sais que le support influence le résultat d’une création.'],
  ['Confondre forme géométrique et forme organique.','Croire que le format d’une œuvre n’a aucune importance.','Ignorer que le support (papier, toile, bois) change le résultat.'],
  ['Géométrique : règles précises (cercle, carré…).','Organique : contours irréguliers, inspiré du vivant.','Format, cadrage, support influencent la perception.']),
 g:mix([sort({'Forme géométrique':['un carré','un triangle','un cercle','un rectangle'],'Forme organique':['une feuille d’arbre','un nuage','une tache d’encre irrégulière','un galet']},{q:'« %s » est une forme…'}),2],
  [bank([
   ['Une forme géométrique se caractérise par…','des contours réguliers qui suivent des règles précises',['des contours toujours irréguliers','l’absence totale de contour','une seule couleur obligatoire'],'Carré, cercle, triangle en sont des exemples.'],
   ['Une forme organique se caractérise par…','des contours irréguliers, inspirés du vivant',['des angles toujours droits','une symétrie parfaite obligatoire','l’absence de toute courbe'],'Elle évoque des formes naturelles.'],
   ['Le format d’une œuvre désigne…','sa taille et ses proportions',['uniquement sa couleur dominante','uniquement son prix','uniquement son auteur'],'Un format très allongé donne une impression différente d’un format carré.'],
   ['Le cadrage d’une image désigne…','ce qui est inclus ou exclu de la représentation',['la couleur utilisée','le poids du support','le nombre de spectateurs'],'Il détermine ce que l’on voit et ce que l’on ne voit pas.'],
   ['Le support d’une œuvre peut être…','du papier, de la toile, du bois ou un mur',['uniquement un écran d’ordinateur','uniquement de l’air','uniquement du métal précieux'],'Le choix du support influence le rendu final.'],
   {tf:'Une composition peut combiner des formes géométriques et des formes organiques.',v:true,e:'De nombreuses œuvres mêlent les deux types de formes.'},
   {tf:'Le format d’une œuvre n’a jamais aucune influence sur sa perception.',v:false,e:'Un format très grand ou très petit modifie la perception de l’œuvre.',d:2}]),2])},

{id:'arts6b',name:'Couleur, matière et texture',icon:'🎨',domain:'Pratique artistique',
 refs:[BO,EDU],
 tip:'Les couleurs primaires (rouge, jaune, bleu) permettent, en les mélangeant, d’obtenir les couleurs secondaires (orange, vert, violet).',
 c:C(`La <b>couleur</b> et la <b>texture</b> (l’aspect d’une surface au toucher ou visuellement) sont des outils essentiels de création, que l’on peut combiner de nombreuses façons.`,
  [T('Couleurs primaires et secondaires',`<p>Les couleurs <b>primaires</b> (rouge, jaune, bleu) ne peuvent pas s’obtenir par mélange d’autres couleurs. En les mélangeant deux à deux, on obtient les couleurs <b>secondaires</b> : rouge + jaune = orange ; jaune + bleu = vert ; bleu + rouge = violet. Les couleurs <b>chaudes</b> (rouge, orange, jaune) évoquent souvent la chaleur et l’énergie ; les couleurs <b>froides</b> (bleu, vert, violet) évoquent le calme ou la fraîcheur.</p>`),
   T('La texture',`<p>La <b>texture</b> est l’aspect d’une surface, lisse ou rugueuse, qu’on peut percevoir visuellement ou au toucher. En arts plastiques, on peut créer des textures en variant les <b>outils</b> (pinceau, éponge, doigts) ou les <b>matériaux</b> (sable, tissu, papier froissé) ajoutés à une composition.</p>`),
   HE('Réaliser une composition en couleurs utilisant au moins 2 couleurs primaires mélangées.','Peindre ou colorier une composition simple en mélangeant deux couleurs primaires pour obtenir au moins une couleur secondaire.','30 minutes.','Peinture ou feutres de couleur, papier, pinceau si peinture.','Protéger la table de travail ; se laver les mains après usage de peinture.','Ai-je bien obtenu une couleur secondaire en mélangeant deux primaires ? Ma composition est-elle cohérente en couleurs chaudes ou froides ?')],
  [{q:'Un élève veut obtenir du vert sans utiliser de peinture verte. Comment faire ?',s:['Mélanger du jaune et du bleu, deux couleurs primaires.','Le vert est une couleur secondaire obtenue par ce mélange.','La proportion de chaque couleur influence la nuance de vert obtenue.']}],
  ['Je connais les couleurs primaires et comment obtenir les couleurs secondaires.','Je distingue couleurs chaudes et couleurs froides.','Je sais ce qu’est une texture en arts plastiques.','Je sais créer différentes textures avec des outils ou matériaux variés.'],
  ['Confondre couleur primaire et couleur secondaire.','Croire que le vert est une couleur primaire.','Ignorer que la texture peut être créée par différents outils ou matériaux.'],
  ['Primaires : rouge, jaune, bleu (non mélangeables).','Secondaires : orange, vert, violet (par mélange).','Texture : aspect d’une surface, variable selon les outils.']),
 g:mix([pairs([['rouge et jaune','orange'],['jaune et bleu','vert'],['bleu et rouge','violet']],{q:'Le mélange de %s donne…',rq:'Quel mélange donne : %s ?'}),2],
  [sort({'Couleur chaude':['le rouge','l’orange','le jaune'],'Couleur froide':['le bleu','le vert','le violet']},{q:'« %s » est une couleur…'}),1],
  [bank([
   ['Les couleurs primaires sont…','le rouge, le jaune et le bleu',['le rouge, le vert et le violet','le orange, le vert et le violet uniquement','le noir, le blanc et le gris'],'Elles ne peuvent pas s’obtenir par mélange d’autres couleurs.'],
   ['Une couleur secondaire s’obtient…','en mélangeant deux couleurs primaires',['en utilisant une seule couleur primaire','en ajoutant uniquement de l’eau','sans aucun mélange'],'Orange, vert et violet en sont des exemples.'],
   ['La texture d’une surface désigne…','son aspect visuel ou tactile, lisse ou rugueux',['uniquement sa couleur','uniquement sa taille','uniquement son prix'],'Elle peut varier selon les outils et matériaux utilisés.'],
   ['Pour créer une texture rugueuse en peinture, on peut…','utiliser une éponge ou ajouter du sable à la peinture',['utiliser uniquement un pinceau fin et de l’eau claire','ne rien ajouter du tout','utiliser uniquement une règle'],'Différents outils et matériaux donnent des effets différents.'],
   {tf:'Le vert est une couleur secondaire obtenue en mélangeant le jaune et le bleu.',v:true,e:'C’est un mélange de deux couleurs primaires.'},
   {tf:'Les couleurs chaudes évoquent généralement la fraîcheur et le calme.',v:false,e:'Ce sont plutôt les couleurs froides qui évoquent cela ; les couleurs chaudes évoquent la chaleur et l’énergie.',d:2}]),2])},

{id:'arts6c',name:'Représenter l’espace et la profondeur',icon:'📐',domain:'Représentation',
 refs:[BO,EDU],
 tip:'Pour donner une impression de profondeur sans perspective complexe, on peut simplement faire les éléments proches plus grands et plus bas sur la feuille, et les éléments lointains plus petits et plus hauts.',
 c:C(`Représenter l’<b>espace</b> et la <b>profondeur</b> sur une surface plane (une feuille) demande d’utiliser des procédés qui donnent l’illusion de la troisième dimension.`,
  [T('Des procédés simples',`<p>Pour suggérer la profondeur sans technique complexe, on peut jouer sur la <b>taille</b> (les éléments proches sont plus grands, les éléments lointains plus petits) et la <b>position</b> sur la feuille (les éléments proches sont placés plus bas, les éléments lointains plus haut, vers la ligne d’horizon).</p>`),
   T('Superposition et plans',`<p>La <b>superposition</b> (un élément qui en cache partiellement un autre) indique lequel est devant et lequel est derrière. On distingue aussi des <b>plans</b> : le <b>premier plan</b> (le plus proche), le plan <b>intermédiaire</b>, et l’<b>arrière-plan</b> (le plus lointain, souvent le ciel ou l’horizon).</p>`),
   HE('Réaliser un dessin de paysage avec au moins trois plans.','Dessiner un paysage en distinguant clairement un premier plan, un plan intermédiaire et un arrière-plan, en jouant sur la taille et la superposition des éléments.','30 minutes.','Papier, crayons de couleur ou feutres.','Aucun matériel dangereux dans cet atelier.','Ai-je bien distingué trois plans différents ? La taille des éléments varie-t-elle selon leur distance apparente ?')],
  [{q:'Dessine un paysage avec une montagne au loin, des arbres au milieu, et une fleur au premier plan.',s:['La montagne, lointaine, est placée en haut et en petite taille.','Les arbres, à distance intermédiaire, sont de taille moyenne.','La fleur, au premier plan, est placée en bas et en grande taille.']}],
  ['Je sais utiliser la taille pour suggérer la distance (proche = grand, lointain = petit).','Je sais utiliser la position sur la feuille pour suggérer la profondeur.','Je comprends le rôle de la superposition entre éléments.','Je distingue premier plan, plan intermédiaire et arrière-plan.'],
  ['Dessiner tous les éléments d’un paysage à la même taille, sans tenir compte de leur distance.','Placer un élément lointain en bas de la feuille et un élément proche en haut.','Ignorer la superposition pour indiquer ce qui est devant ou derrière.'],
  ['Taille et position suggèrent la distance.','Superposition : devant / derrière.','Premier plan, plan intermédiaire, arrière-plan.']),
 g:mix([sort({'Premier plan':['un élément très grand placé en bas de l’image','un objet qui cache partiellement les autres'],'Arrière-plan':['un élément très petit placé en haut de l’image','la ligne d’horizon ou le ciel']},{q:'« %s » relève plutôt du…'}),2],
  [bank([
   ['Pour suggérer qu’un élément est proche, on le dessine généralement…','grand et placé en bas de la feuille',['petit et placé en haut de la feuille','toujours de couleur rouge','sans aucun contour'],'Taille et position aident à suggérer la distance.'],
   ['Pour suggérer qu’un élément est lointain, on le dessine généralement…','petit et placé en haut de la feuille',['grand et placé en bas de la feuille','toujours en noir et blanc','avec un contour épais'],'Les éléments lointains paraissent plus petits à l’œil.'],
   ['La superposition entre deux éléments indique…','lequel est devant et lequel est derrière',['uniquement leur couleur','uniquement leur taille réelle','rien de particulier'],'Un élément qui en cache un autre est perçu comme plus proche.'],
   ['Le premier plan d’une image désigne…','la partie la plus proche du spectateur',['la partie la plus lointaine','uniquement le centre de l’image','uniquement le ciel'],'Il s’oppose à l’arrière-plan.'],
   {tf:'Jouer sur la taille des éléments permet de suggérer la distance sur une image plane.',v:true,e:'C’est un procédé simple et efficace.'},
   {tf:'Un paysage ne peut jamais être représenté avec plus de deux plans différents.',v:false,e:'On distingue souvent trois plans ou plus (premier plan, plans intermédiaires, arrière-plan).',d:2},
   ['Dessiner la ligne d’horizon plus haut sur la feuille donne généralement l’impression…','d’un grand espace au sol, visible devant soi',['d’un ciel immense sans aucun sol visible','d’une absence totale de profondeur','d’un gros plan uniquement'],'La position de l’horizon influence la composition de l’espace.',2],
   ['Plusieurs objets alignés qui diminuent progressivement de taille sur une image suggèrent…','un éloignement progressif, de proche en lointain',['un rapprochement progressif uniquement','l’absence totale de profondeur','une répétition sans aucun lien avec l’espace'],'Cette diminution progressive aide à représenter une distance qui s’accroît.']]),2])},

{id:'arts6d',name:'Image, récit et imagination',icon:'📖',domain:'Image',
 refs:[BO,EDU],
 tip:'Une image qui raconte une histoire choisit souvent un moment précis et riche en action ou en émotion, plutôt qu’un instant neutre.',
 c:C(`Une image peut <b>raconter une histoire</b> : elle choisit un moment, des personnages, un décor, pour suggérer un récit à celui qui la regarde.`,
  [T('Choisir un moment',`<p>Pour raconter une histoire en une seule image, on choisit un <b>instant</b> particulièrement riche en action, en émotion ou en tension, plutôt qu’un moment neutre. Les détails du décor et des expressions des personnages donnent des <b>indices</b> sur ce qui s’est passé avant et ce qui va suivre.</p>`),
   T('Imaginer et inventer',`<p>L’<b>imagination</b> permet d’inventer des personnages, des créatures ou des mondes qui n’existent pas dans la réalité, en s’inspirant parfois d’éléments réels combinés de façon nouvelle. Une image imaginaire reste souvent plus <b>crédible</b> si certains détails restent cohérents entre eux (proportions, lumière).</p>`),
   HE('Illustrer un moment clé d’une histoire inventée.','Inventer une courte histoire en 3 phrases, puis dessiner l’image du moment le plus important de cette histoire.','30 minutes.','Papier, crayons de couleur ou feutres.','Aucun matériel dangereux.','Mon image donne-t-elle des indices sur ce qui précède et ce qui suit ce moment ? L’histoire est-elle reconnaissable à partir de l’image seule ?')],
  [{q:'Illustre le moment où un personnage découvre un trésor caché dans une grotte.',s:['Choisir l’instant précis de la découverte, riche en émotion.','Montrer l’expression de surprise ou de joie du personnage.','Ajouter des détails de décor (lumière, objets) qui enrichissent le récit.']}],
  ['Je sais choisir un instant riche en action ou en émotion pour raconter une histoire.','Je sais utiliser des détails pour donner des indices sur le récit.','Je sais inventer des personnages ou des mondes imaginaires.','Je comprends l’intérêt de garder une cohérence dans les détails d’une image imaginaire.'],
  ['Choisir un moment neutre, sans aucune action ni émotion, pour illustrer une histoire.','Ignorer les détails qui pourraient enrichir le récit suggéré.','Créer une image imaginaire totalement incohérente dans ses proportions ou sa lumière.'],
  ['Choisir un instant riche en action/émotion.','Détails = indices sur le récit.','Imagination + cohérence des détails.']),
 g:mix([bank([
  ['Pour raconter une histoire en une seule image, il est préférable de choisir…','un instant riche en action ou en émotion',['un moment neutre, sans aucune action','le moment le plus calme possible','un instant sans aucun personnage'],'Cela donne plus d’indices sur le récit suggéré.'],
  ['Les détails du décor dans une image narrative servent à…','donner des indices sur ce qui s’est passé avant ou après',['décorer sans aucune autre fonction','ralentir la réalisation de l’image','remplacer les personnages'],'Ils enrichissent la compréhension du récit.'],
  ['Une image imaginaire reste souvent plus crédible si…','certains détails (proportions, lumière) restent cohérents entre eux',['aucun élément n’est cohérent','elle ne contient aucun détail','elle copie exactement la réalité'],'La cohérence interne aide à rendre l’image convaincante.'],
  ['Inventer un personnage imaginaire peut s’appuyer sur…','la combinaison nouvelle d’éléments réels',['uniquement la copie exacte d’un animal existant','l’absence totale de référence au réel','uniquement des formes géométriques simples'],'On recombine souvent des éléments connus de façon originale.'],
  {tf:'Une image peut suggérer un récit sans avoir besoin de texte.',v:true,e:'Les détails visuels suffisent souvent à raconter une histoire.'},
  {tf:'Le choix du moment représenté n’a aucune influence sur la force narrative d’une image.',v:false,e:'Un instant riche en action ou en émotion renforce généralement le récit suggéré.',d:2},
  ['L’expression du visage d’un personnage dans une image narrative aide notamment à…','comprendre son émotion face à la situation représentée',['remplacer totalement le décor','masquer systématiquement l’action en cours','ralentir la lecture de l’image sans aucun bénéfice'],'Le visage transmet une information émotionnelle importante.'],
  ['Associer plusieurs images successives peut-il permettre de raconter une histoire plus développée qu’avec une seule image ?','oui, comme dans une bande dessinée',['non, une seule image suffit toujours pour tout raconter','non, plusieurs images rendent toujours l’histoire incompréhensible','non, cela n’existe dans aucune forme artistique'],'La succession d’images permet de développer un récit sur plusieurs étapes.'],
  ['Un décor sombre et orageux dans une image narrative suggère souvent une ambiance…','inquiétante ou menaçante',['toujours joyeuse et paisible','sans aucun lien avec l’émotion du récit','obligatoirement comique'],'Les éléments du décor participent à l’atmosphère générale de l’image.'],
  ['La posture d’un personnage (debout fièrement ou recroquevillé) peut-elle donner des indices sur son état émotionnel dans un récit imagé ?','oui, la posture contribue souvent à exprimer un état émotionnel',['non, la posture n’a jamais aucun sens','non, seul le visage transmet des informations','non, cela dépend uniquement de la couleur utilisée'],'Le langage corporel enrichit la narration visuelle.'],
  ['Mélanger des éléments réels (un animal connu) avec des éléments inventés (des ailes, une couleur impossible) crée…','une créature imaginaire reconnaissable mais nouvelle',['une copie exacte de la réalité','une image totalement incompréhensible','un objet géométrique uniquement'],'C’est une méthode fréquente pour inventer des personnages imaginaires.'],
  ['Une image qui ne montre que les conséquences d’un événement (par exemple des objets renversés), sans montrer l’événement lui-même, peut-elle suggérer une histoire ?','oui, le spectateur peut imaginer ce qui a précédé ce moment',['non, il faut toujours montrer l’événement central lui-même','non, les conséquences ne racontent jamais rien','non, cela rend toujours l’image incompréhensible'],'Suggérer plutôt que montrer peut stimuler l’imagination du spectateur.',3]]),2])},

{id:'arts6e',name:'Objet, fabrication et détournement',icon:'🔧',domain:'Objet',
 refs:[BO,EDU],
 tip:'Détourner un objet, c’est lui donner un nouvel usage ou un nouveau sens différent de sa fonction d’origine : une vieille roue de vélo peut devenir une sculpture.',
 c:C(`Au-delà du dessin et de la peinture, les arts plastiques explorent la <b>fabrication</b> d’objets en volume, et leur <b>détournement</b> : donner un nouveau sens à un objet existant.`,
  [T('Fabriquer en volume',`<p>Travailler en <b>volume</b> (en trois dimensions) demande de penser un objet de tous les côtés, pas seulement de face. On peut <b>assembler</b> des matériaux divers (carton, papier, objets de récupération) pour construire une forme qui tient debout et qui peut être observée sous plusieurs angles.</p>`),
   T('Le détournement d’objet',`<p>Le <b>détournement</b> consiste à donner à un objet existant une <b>fonction</b> ou un <b>sens</b> différent de celui pour lequel il a été conçu : une roue de vélo devient une sculpture, une cuillère devient un personnage. Cette démarche questionne le rapport habituel qu’on a avec les objets du quotidien.</p>`),
   HE('Détourner un objet du quotidien pour lui donner un nouveau sens.','Choisir un petit objet du quotidien (bouchon, cuillère, boîte) et le transformer ou l’assembler avec d’autres éléments pour lui donner un nouveau sens.','30 minutes.','Un objet de récupération, colle, éventuellement peinture ou papier.','Demander l’accord d’un adulte avant d’utiliser un objet qui ne vous appartient pas ; prudence avec la colle et les petits objets.','Mon objet a-t-il un nouveau sens, différent de sa fonction d’origine ? Ai-je pensé mon objet sous plusieurs angles ?')],
  [{q:'Un élève transforme une vieille fourchette en personnage miniature.',s:['Il détourne l’objet de sa fonction d’origine (manger).','La fourchette devient un support pour une nouvelle forme (un personnage).','Cette démarche questionne le regard habituel sur les objets du quotidien.']}],
  ['Je sais ce que signifie travailler en volume (trois dimensions).','Je sais assembler des matériaux de récupération pour créer une forme.','Je comprends ce qu’est le détournement d’un objet.','Je sais qu’un objet détourné prend un sens différent de sa fonction d’origine.'],
  ['Ne penser une forme en volume que de face, sans considérer les autres angles.','Confondre détourner un objet et simplement le décorer sans changer son sens.','Utiliser un objet qui ne vous appartient pas sans demander l’accord d’un adulte.'],
  ['Volume = penser une forme de tous les côtés.','Assemblage de matériaux de récupération.','Détournement = nouveau sens, fonction différente.']),
 g:mix([bank([
  ['Travailler « en volume », en arts plastiques, signifie…','créer une forme en trois dimensions, observable sous plusieurs angles',['dessiner uniquement sur une feuille plate','utiliser uniquement de la peinture','travailler uniquement en noir et blanc'],'Contrairement à un dessin, un volume se regarde de tous les côtés.'],
  ['Le détournement d’un objet consiste à…','lui donner un usage ou un sens différent de celui d’origine',['le jeter définitivement','le ranger sans le modifier','le photographier uniquement'],'Une roue de vélo peut ainsi devenir une sculpture.'],
  ['Pourquoi penser un volume sous plusieurs angles avant de le fabriquer ?','car il sera observé de tous les côtés, pas seulement de face',['ce n’est jamais nécessaire','car un volume n’a toujours qu’une seule face visible','par pure habitude sans raison précise'],'Une forme en trois dimensions se perçoit différemment selon l’angle de vue.'],
  ['Pour fabriquer un objet en volume avec des matériaux de récupération, on utilise souvent…','du carton, du papier ou des objets divers assemblés',['uniquement de la peinture liquide','uniquement un écran d’ordinateur','uniquement de l’eau'],'Divers matériaux peuvent être combinés pour créer une forme.'],
  {tf:'Le détournement d’un objet interroge le rapport habituel qu’on a avec les objets du quotidien.',v:true,e:'C’est l’un des intérêts de cette démarche artistique.'},
  {tf:'Un objet détourné garde obligatoirement exactement la même fonction qu’à l’origine.',v:false,e:'C’est justement le contraire : le détournement change sa fonction ou son sens.',d:2},
  ['Combiner plusieurs petits objets de récupération pour créer une forme nouvelle relève…','de l’assemblage, une démarche fréquente en volume',['d’une interdiction en arts plastiques','du dessin uniquement','de la seule photographie'],'L’assemblage est une technique courante pour créer en trois dimensions.'],
  ['Pourquoi demander l’accord d’un adulte avant d’utiliser un objet pour une création artistique ?','car l’objet peut appartenir à quelqu’un d’autre ou avoir une utilité importante',['ce n’est jamais nécessaire','car cela ralentit toujours la création sans raison','car cela est interdit par la loi dans tous les cas'],'Le respect du bien d’autrui reste une règle de base.',2],
  ['Un objet détourné peut-il garder des traces visibles de sa fonction d’origine, tout en prenant un nouveau sens ?','oui, ces traces peuvent même enrichir la lecture de l’œuvre',['non, toute trace de la fonction d’origine doit toujours être effacée','non, un objet détourné perd toujours totalement sa forme initiale','non, cela rendrait l’œuvre incompréhensible'],'Le contraste entre fonction d’origine et nouveau sens peut être intéressant.'],
  ['Choisir des objets de tailles ou de couleurs variées pour un assemblage en volume peut-il enrichir le résultat visuel ?','oui, la variété rend souvent la composition plus intéressante',['non, tous les éléments doivent toujours être identiques','non, la couleur n’a jamais aucune importance en volume','non, la variété rend toujours le résultat confus'],'La diversité des éléments assemblés peut créer du rythme visuel.'],
  ['Un objet fabriqué en volume doit-il forcément être solide et stable pour être présenté ?','oui, il doit généralement tenir debout seul pour être observé',['non, la stabilité n’a jamais aucune importance','non, il peut toujours reposer uniquement sur un support extérieur caché','non, cela ne concerne que les sculptures en pierre'],'La stabilité permet d’observer l’objet sous tous ses angles sans qu’il ne s’effondre.'],
  ['Reproduire plusieurs fois un même petit élément assemblé peut-il créer un effet de rythme dans une composition en volume ?','oui, la répétition d’un motif crée souvent un effet visuel de rythme',['non, la répétition n’a jamais aucun effet visuel','non, il faut toujours utiliser des éléments tous différents','non, cela concerne uniquement la musique'],'La répétition est un procédé courant en composition plastique.',3]]),2])},

{id:'arts6f',name:'Présenter une production et expliquer ses choix',icon:'🗣️',domain:'Oral artistique',
 refs:[BO,EDU],
 tip:'Pour présenter sa production, explique ce que tu as voulu montrer, comment tu l’as fait (techniques, matériaux), et ce que tu en penses maintenant qu’elle est terminée.',
 c:C(`Après avoir réalisé une production, il est important de savoir la <b>présenter</b> et <b>expliquer</b> les choix qui ont guidé sa réalisation.`,
  [T('Expliquer ses intentions',`<p>Présenter sa production commence par expliquer ce qu’on a voulu <b>montrer</b> ou <b>exprimer</b> : une idée, une émotion, une histoire. On précise les <b>techniques</b> et <b>matériaux</b> utilisés, et les choix faits en cours de réalisation (couleurs, formes, composition).</p>`),
   T('Recevoir un avis sur sa production',`<p>Écouter l’avis des autres sur sa propre production demande d’être ouvert à la <b>critique</b>, sans se sentir attaqué personnellement : une remarque sur l’œuvre n’est pas une remarque sur la personne. On peut aussi exprimer son propre avis sur ce qui a bien ou moins bien fonctionné dans sa réalisation.</p>`),
   HE('Présenter oralement une production réalisée en classe.','Présenter en 1 minute une production personnelle : intention, techniques utilisées, et avis personnel sur le résultat.','10 minutes de préparation, 1 minute de présentation.','La production réalisée précédemment.','Aucune sécurité particulière pour cette activité orale.','Ai-je expliqué mon intention de départ ? Ai-je précisé les techniques et matériaux utilisés ?')],
  [{q:'Présente une production représentant un paysage imaginaire en couleurs vives.',s:['Intention : représenter un monde imaginaire joyeux.','Techniques : peinture avec des couleurs primaires mélangées pour obtenir des teintes variées.','Avis personnel : satisfait du résultat, mais le ciel pourrait être retravaillé.']}],
  ['Je sais expliquer l’intention de ma production.','Je sais préciser les techniques et matériaux utilisés.','Je sais écouter une critique sur mon œuvre sans la prendre personnellement.','Je sais donner mon propre avis sur ma réalisation.'],
  ['Présenter une production sans expliquer aucune intention.','Confondre une critique de l’œuvre avec une attaque personnelle.','Refuser d’écouter tout avis différent du sien sur sa production.'],
  ['Expliquer l’intention : quoi, pourquoi.','Préciser techniques et matériaux.','Écouter une critique sans la prendre personnellement.']),
 g:mix([bank([
  ['Présenter sa production commence généralement par…','expliquer l’intention de départ (ce qu’on a voulu montrer ou exprimer)',['donner immédiatement son avis sur les autres productions','ignorer complètement sa propre intention','parler uniquement du prix des matériaux utilisés'],'L’intention éclaire les choix faits ensuite.'],
  ['Une critique sur une œuvre réalisée est-elle une attaque contre la personne qui l’a créée ?','non, elle porte sur l’œuvre, pas sur la personne',['oui, toujours une attaque personnelle','oui, il faut toujours se sentir blessé','oui, sauf si la critique est positive'],'Il est utile de distinguer l’œuvre de son auteur lors d’une critique.'],
  ['Préciser les techniques et matériaux utilisés dans une présentation permet…','de mieux comprendre comment la production a été réalisée',['de rendre la présentation plus confuse','de cacher les choix faits','de remplacer totalement l’intention'],'Cela éclaire la démarche de création.'],
  ['Donner son propre avis sur sa production, après l’avoir présentée, permet…','de montrer une réflexion sur son propre travail',['de ne jamais devoir expliquer ses choix','d’éviter toute critique extérieure','de remplacer la présentation elle-même'],'L’autoévaluation fait partie de la démarche artistique.'],
  {tf:'Expliquer ses choix techniques fait partie d’une bonne présentation de production artistique.',v:true,e:'Cela éclaire la démarche suivie pour réaliser l’œuvre.'},
  {tf:'Il faut toujours se sentir personnellement attaqué quand quelqu’un critique une œuvre qu’on a réalisée.',v:false,e:'Une critique porte sur l’œuvre, pas sur la personne qui l’a créée.',d:2},
  ['Parler suffisamment fort et clairement en présentant sa production fait partie…','des compétences de communication orale utiles à la présentation',['d’une règle sans aucun lien avec la présentation','d’une compétence réservée aux acteurs professionnels','d’un détail totalement secondaire'],'Être bien entendu et compris fait partie d’une bonne présentation.'],
  ['Si une production n’est pas totalement réussie selon son auteur, est-il utile de le reconnaître lors de la présentation ?','oui, cela montre une réflexion honnête sur son propre travail',['non, il faut toujours prétendre que tout est parfait','non, cela n’a jamais aucun intérêt','non, il vaut mieux ne jamais en parler'],'L’autoévaluation honnête enrichit la présentation.'],
  ['Préparer quelques phrases avant de présenter sa production à l’oral peut-il aider à être plus clair ?','oui, une petite préparation aide à organiser son discours',['non, il vaut mieux ne jamais rien préparer','non, cela rend toujours la présentation moins naturelle','non, la préparation est interdite pour cet exercice'],'Une préparation légère aide sans rendre le discours récité.'],
  ['Comparer sa production à l’intention de départ permet-il de mieux évaluer ce qui a été réalisé ?','oui, cela aide à mesurer l’écart entre le projet et le résultat final',['non, cela n’a jamais aucune utilité','non, l’intention de départ doit toujours être oubliée','non, seul le résultat final compte, sans aucun lien avec l’intention'],'Cette comparaison nourrit une autoévaluation constructive.'],
  ['Montrer sa production en même temps qu’on la décrit peut-il faciliter la compréhension du public pendant la présentation ?','oui, le support visuel appuie souvent efficacement le discours',['non, il vaut mieux toujours cacher la production pendant qu’on en parle','non, cela complique toujours inutilement la présentation','non, le public comprend toujours sans voir l’œuvre'],'Associer la parole et l’observation directe aide à la compréhension.'],
  ['Noter quelques mots-clés plutôt qu’un texte entier avant une présentation orale peut-il aider à rester naturel ?','oui, les mots-clés guident le discours sans pousser à le réciter mot à mot',['non, il vaut toujours mieux ne rien noter du tout','non, un texte entier appris par cœur est toujours préférable','non, les mots-clés rendent toujours la présentation confuse'],'Un support léger aide à structurer sans sacrifier le naturel.']]),2])}
]);

MQ.add('arts','5',[
{id:'arts5a',name:'Composer une image et organiser l’espace',icon:'🖼️',domain:'Composition',
 refs:[BO,EDU],
 tip:'Placer l’élément principal légèrement décalé du centre, plutôt qu’exactement au milieu, rend souvent une composition plus dynamique.',
 c:C(`Composer une image, c’est organiser consciemment les <b>éléments</b> dans l’espace disponible, pour guider le regard du spectateur et créer un équilibre (ou un déséquilibre volontaire).`,
  [T('Équilibre et déséquilibre',`<p>Une composition <b>symétrique</b> (équilibrée de part et d’autre d’un axe) donne une impression de calme et de stabilité. Une composition <b>asymétrique</b> (déséquilibrée volontairement) peut créer du <b>dynamisme</b> ou de la tension. Répartir le <b>poids visuel</b> (zones sombres, éléments grands) dans l’espace influence cette impression d’équilibre.</p>`),
   T('Guider le regard',`<p>Des <b>lignes directrices</b> (réelles ou suggérées) dans une image peuvent guider le regard du spectateur vers un point précis. Placer l’élément principal au <b>centre</b> ou légèrement <b>décalé</b> produit des effets différents : le centre attire immédiatement l’œil, un léger décalage crée du mouvement.</p>`),
   HE('Réaliser deux compositions avec le même sujet : une symétrique, une asymétrique.','Dessiner deux fois le même sujet simple (par exemple un arbre), une fois centré de façon symétrique, une fois décalé de façon asymétrique.','30 minutes.','Papier, crayons ou feutres.','Aucun matériel dangereux dans cet atelier.','Les deux compositions donnent-elles des impressions différentes ? Ai-je bien respecté la symétrie et l’asymétrie demandées ?')],
  [{q:'Compare une photo de portrait centré et une photo du même portrait décalé sur le côté.',s:['Le portrait centré donne une impression de stabilité et de confrontation directe.','Le portrait décalé laisse de l’espace et peut suggérer un mouvement ou une direction.','Le choix de composition dépend de l’effet recherché par le photographe.']}],
  ['Je distingue composition symétrique et composition asymétrique.','Je comprends l’effet du poids visuel dans une composition.','Je sais ce qu’est une ligne directrice dans une image.','Je comprends l’effet d’un élément centré ou décalé.'],
  ['Confondre symétrie et asymétrie.','Ignorer l’effet du poids visuel (zones sombres, grands éléments) sur l’équilibre.','Croire qu’un élément centré et un élément décalé produisent toujours le même effet.'],
  ['Symétrique = calme ; asymétrique = dynamisme.','Poids visuel = équilibre de la composition.','Lignes directrices guident le regard.']),
 g:mix([sort({'Composition symétrique':['un élément identique répété de chaque côté d’un axe central','un visage photographié exactement de face et centré'],'Composition asymétrique':['un élément unique placé sur le côté droit de l’image','un sujet décalé, laissant un grand espace vide à gauche']},{q:'« %s » relève d’une composition…'}),2],
  [bank([
   ['Une composition symétrique donne généralement une impression de…','calme et de stabilité',['mouvement violent uniquement','désordre total','absence totale de sujet'],'L’équilibre de part et d’autre d’un axe rassure le regard.'],
   ['Une composition asymétrique peut créer…','du dynamisme ou de la tension',['uniquement de l’ennui','uniquement de la symétrie parfaite','aucun effet particulier'],'Le déséquilibre volontaire capte l’attention.'],
   ['Le « poids visuel » d’un élément dans une image dépend notamment de…','sa taille et de sa couleur (sombre ou claire)',['uniquement son prix','uniquement sa date de création','uniquement son auteur'],'Un grand élément sombre pèse visuellement plus qu’un petit élément clair.'],
   ['Une ligne directrice dans une image sert à…','guider le regard du spectateur vers un point précis',['remplacer totalement le sujet principal','ralentir systématiquement la lecture de l’image','cacher le sujet principal'],'Elle peut être réelle (un chemin) ou suggérée (une direction de regard).'],
   {tf:'Placer un élément légèrement décalé du centre peut rendre une composition plus dynamique.',v:true,e:'Le centre exact donne plutôt une impression de stabilité.'},
   {tf:'Une composition asymétrique est toujours moins réussie qu’une composition symétrique.',v:false,e:'Les deux peuvent être réussies, selon l’effet recherché.',d:2},
  ['Laisser un grand espace vide d’un côté de l’image peut-il attirer l’œil vers l’élément placé de l’autre côté ?','oui, le vide fait souvent ressortir l’élément présent',['non, le vide n’a jamais aucun effet','non, cela rend toujours la composition incompréhensible','non, il faut toujours remplir tout l’espace disponible'],'Le contraste entre vide et plein guide la lecture de l’image.',2],
  ['Un format d’image très allongé horizontalement convient-il particulièrement à la représentation d’un vaste paysage ?','oui, ce format accompagne souvent une impression d’étendue horizontale',['non, un format carré convient toujours mieux à un paysage','non, le format n’a jamais aucun lien avec le sujet représenté','non, un format allongé verticalement convient toujours mieux'],'Le format choisi peut renforcer l’effet recherché.']]),2])},

{id:'arts5b',name:'Couleurs, contrastes et lumière',icon:'💡',domain:'Pratique artistique',
 refs:[BO,EDU],
 tip:'Un fort contraste de clarté (une zone très claire près d’une zone très sombre) attire immédiatement le regard sur cette zone.',
 c:C(`Au-delà des couleurs primaires et secondaires, on explore les <b>contrastes</b> de couleur et de lumière, qui créent des effets visuels puissants.`,
  [T('Les contrastes de couleur',`<p>Des couleurs <b>complémentaires</b> (opposées sur le cercle chromatique, comme le rouge et le vert, ou le bleu et l’orange) créent un contraste <b>fort</b> et vibrant quand elles sont placées côte à côte. Un contraste de <b>clarté</b> (clair contre sombre) attire fortement l’œil, indépendamment de la couleur utilisée.</p>`),
   T('La lumière dans une représentation',`<p>Représenter la <b>lumière</b> demande de penser aux <b>ombres</b> qu’elle projette : une source de lumière éclaire certaines faces d’un objet et laisse d’autres faces dans l’ombre. Le <b>clair-obscur</b> (fort contraste entre zones très claires et très sombres) crée une ambiance dramatique, utilisée par de nombreux artistes (voir le peintre Caravage, étudié en histoire des arts).</p>`),
   HE('Réaliser une composition utilisant un contraste de couleurs complémentaires.','Peindre ou colorier une composition simple en utilisant uniquement deux couleurs complémentaires (par exemple rouge et vert).','30 minutes.','Peinture ou feutres de couleur, papier.','Protéger la table de travail si utilisation de peinture.','Ai-je bien utilisé deux couleurs complémentaires ? Le contraste est-il visible et volontaire ?')],
  [{q:'Un peintre veut faire ressortir un personnage sur un fond. Comment utiliser le contraste ?',s:['Choisir une couleur très différente en clarté entre le personnage et le fond.','Ou utiliser des couleurs complémentaires pour un contraste coloré fort.','Le contraste attire l’œil directement sur le personnage.']}],
  ['Je connais le principe des couleurs complémentaires.','Je comprends l’effet d’un contraste de clarté.','Je sais comment représenter l’ombre projetée par une source de lumière.','Je connais le clair-obscur et un exemple d’artiste qui l’a utilisé.'],
  ['Confondre couleurs complémentaires et couleurs identiques.','Ignorer l’effet d’un fort contraste de clarté sur l’attention du regard.','Oublier de représenter les ombres projetées par une lumière.'],
  ['Couleurs complémentaires : contraste fort et vibrant.','Contraste de clarté : attire l’œil.','Clair-obscur : ombre et lumière dramatiques.']),
 g:mix([pairs([['le rouge','le vert'],['le bleu','l’orange'],['le jaune','le violet']],{q:'La couleur complémentaire de %s est…',rq:'Quelle couleur a pour complémentaire : %s ?'}),2],
  [bank([
   ['Des couleurs complémentaires, placées côte à côte, créent…','un contraste fort et vibrant',['toujours une couleur grise neutre','aucun effet visuel particulier','toujours une impression de calme total'],'Elles s’opposent sur le cercle chromatique.'],
   ['Un contraste de clarté (clair contre sombre) attire…','fortement le regard, quelle que soit la couleur utilisée',['uniquement si les couleurs sont complémentaires','jamais le regard','uniquement en noir et blanc strict'],'La différence de clarté capte l’attention indépendamment de la teinte.'],
   ['Le clair-obscur désigne…','un fort contraste entre zones très claires et très sombres',['l’absence totale de contraste','uniquement l’usage du gris','uniquement les couleurs pastel'],'Il crée souvent une ambiance dramatique.'],
   ['Représenter une ombre projetée demande de penser à…','la direction de la source de lumière',['uniquement la couleur du sol','uniquement la taille de l’objet','rien de particulier'],'La position de la lumière détermine la direction et la forme de l’ombre.'],
   {tf:'Les couleurs complémentaires sont opposées sur le cercle chromatique.',v:true,e:'Rouge-vert, bleu-orange, jaune-violet en sont des exemples.'},
   {tf:'Le clair-obscur consiste à utiliser uniquement des teintes pastel, sans aucun contraste.',v:false,e:'Il s’agit au contraire d’un contraste fort entre lumière et ombre.',d:2}]),2])},

{id:'arts5c',name:'Corps, geste et trace',icon:'✋',domain:'Pratique artistique',
 refs:[BO,EDU],
 tip:'Un geste rapide et ample laisse une trace différente d’un geste lent et précis : la vitesse et l’amplitude du mouvement influencent directement le résultat visuel.',
 c:C(`Le <b>corps</b> et le <b>geste</b> de l’artiste laissent une <b>trace</b> visible dans l’œuvre : la façon de bouger influence directement le résultat obtenu.`,
  [T('Le geste comme outil',`<p>Un geste <b>rapide</b> et <b>ample</b> (grand mouvement du bras) laisse une trace différente d’un geste <b>lent</b> et <b>précis</b> (petit mouvement des doigts). La <b>pression</b> exercée (appuyer fort ou effleurer) influence aussi l’épaisseur et l’intensité de la trace laissée.</p>`),
   T('Le corps dans la création',`<p>Certains artistes utilisent leur corps entier pour créer (peindre en marchant, en dansant, en projetant de la peinture). Le <b>corps</b> peut aussi devenir le sujet même de l’œuvre : empreintes de mains, silhouettes tracées, performances où le corps de l’artiste est l’outil principal.</p>`),
   HE('Réaliser plusieurs traces en variant la vitesse et la pression du geste.','Avec un crayon ou un pinceau, réaliser 4 traces différentes : rapide et légère, rapide et appuyée, lente et légère, lente et appuyée. Comparer les résultats.','20 minutes.','Crayon ou pinceau, papier, peinture éventuellement.','Protéger la table si utilisation de peinture.','Les 4 traces sont-elles bien différentes ? Ai-je identifié quel geste correspond à quelle trace ?')],
  [{q:'Compare une trace de peinture obtenue par un geste rapide et une trace obtenue par un geste lent.',s:['Le geste rapide laisse souvent une trace plus fluide, parfois moins précise.','Le geste lent permet un contrôle plus précis du tracé.','Le choix du geste dépend de l’effet recherché par l’artiste.']}],
  ['Je sais que la vitesse du geste influence la trace laissée.','Je sais que la pression exercée influence l’épaisseur de la trace.','Je connais des démarches artistiques utilisant le corps entier.','Je comprends que le corps peut être à la fois outil et sujet d’une œuvre.'],
  ['Croire que tous les gestes produisent toujours la même trace.','Ignorer l’effet de la pression sur l’épaisseur d’une trace.','Penser que le corps ne peut jamais être le sujet d’une œuvre.'],
  ['Vitesse et amplitude du geste influencent la trace.','Pression influence l’épaisseur et l’intensité.','Corps : outil de création et parfois sujet de l’œuvre.']),
 g:mix([bank([
  ['Un geste rapide et ample laisse généralement une trace…','plus fluide, parfois moins précise',['toujours identique à un geste lent','toujours plus précise qu’un geste lent','sans aucune différence visible'],'La vitesse influence la qualité du tracé.'],
  ['Appuyer fortement avec un crayon ou un pinceau produit généralement une trace…','plus épaisse ou plus intense',['identique à un effleurement léger','toujours invisible','toujours de couleur différente'],'La pression influence l’intensité de la trace.'],
  ['Une empreinte de main peut-elle être utilisée comme élément artistique ?','oui, c’est une trace directe du corps',['non, jamais','non, seule la peinture au pinceau est artistique','non, cela n’a aucun lien avec l’art'],'Le corps peut laisser des traces directement exploitables en création.'],
  ['Le corps d’un artiste peut-il devenir le sujet même d’une œuvre, et pas seulement l’outil ?','oui, par exemple dans des performances artistiques',['non, le corps n’est jamais le sujet d’une œuvre','non, cela n’existe dans aucune forme d’art','non, uniquement en sculpture'],'Certaines démarches artistiques font du corps lui-même le sujet de l’œuvre.',2],
  {tf:'La vitesse et la pression du geste influencent directement la trace obtenue.',v:true,e:'Ce sont deux paramètres essentiels du geste artistique.'},
  {tf:'Un geste lent et précis produit toujours exactement le même résultat qu’un geste rapide.',v:false,e:'Les deux gestes produisent généralement des traces différentes.',d:2},
  ['Faire glisser le pinceau en gardant toujours la même pression produit généralement une trace…','régulière, d’épaisseur constante',['toujours irrégulière et aléatoire','toujours invisible','toujours de couleur changeante'],'Une pression constante donne un résultat plus homogène.'],
  ['Varier volontairement la pression pendant un même tracé peut-il créer un effet intéressant ?','oui, la trace peut devenir plus épaisse ou plus fine selon la pression',['non, la pression n’a jamais aucun effet sur la trace','non, il faut toujours garder exactement la même pression','non, cela rend toujours le résultat raté'],'Cette variation peut enrichir visuellement le tracé.'],
  ['Une performance artistique où l’artiste utilise son corps en mouvement devant un public relève…','d’une démarche où le corps devient à la fois outil et sujet de l’œuvre',['uniquement d’une activité sportive sans aucun lien avec l’art','d’une erreur de méthode artistique','d’une simple répétition sans aucune intention'],'Le corps en action peut constituer l’œuvre elle-même.',2],
  ['Tracer une ligne continue sans lever l’outil, sur toute la durée d’un geste, peut-il créer un effet particulier ?','oui, cela peut donner une impression de continuité ou de mouvement ininterrompu',['non, cela ne produit jamais aucun effet','non, il faut toujours lever l’outil très souvent','non, une ligne continue est toujours ratée'],'La continuité du geste influence la lecture de la trace obtenue.'],
  ['Projeter de la peinture sur une surface, plutôt que de la déposer avec un pinceau posé, produit généralement une trace…','plus éclatée et imprévisible',['toujours parfaitement régulière','toujours identique à un trait de pinceau','toujours invisible'],'Cette technique donne un rendu différent d’un geste contrôlé au pinceau.',2],
  ['Observer les traces laissées par un même artiste sur plusieurs œuvres peut-il aider à reconnaître son style gestuel ?','oui, la façon de tracer peut devenir une signature personnelle reconnaissable',['non, cela n’a jamais aucun intérêt','non, deux œuvres d’un même artiste se ressemblent toujours exactement','non, le geste ne laisse jamais de trace reconnaissable'],'Le geste personnel peut devenir une caractéristique du style d’un artiste.',3]]),2])},

{id:'arts5d',name:'Photographie et cadrage',icon:'📷',domain:'Image',
 refs:[BO,EDU],
 tip:'Un cadrage « en plongée » (vu du dessus) donne une impression de domination sur le sujet ; un cadrage « en contre-plongée » (vu du dessous) donne une impression de puissance ou de grandeur au sujet.',
 c:C(`La <b>photographie</b> permet de capturer un instant réel, mais le <b>cadrage</b> choisi par le photographe transforme profondément la perception de la scène.`,
  [T('Les choix de cadrage',`<p>Le <b>plan</b> choisi (gros plan, plan rapproché, plan large) détermine ce qui est visible et à quelle distance apparente. L’<b>angle de vue</b> influence aussi la perception : une <b>plongée</b> (vue du dessus) donne une impression de domination sur le sujet ; une <b>contre-plongée</b> (vue du dessous) donne une impression de puissance ou de grandeur au sujet.</p>`),
   T('Composer une photographie',`<p>La <b>règle des tiers</b> (diviser l’image en 3 bandes horizontales et verticales, et placer le sujet sur ces lignes ou leurs intersections) aide souvent à obtenir une composition équilibrée. Le choix du moment précis du déclenchement (<b>l’instant décisif</b>) est aussi essentiel en photographie, notamment pour capter un mouvement ou une expression.</p>`),
   HE('Prendre deux photographies du même sujet avec des cadrages différents.','Si un appareil photo ou smartphone est disponible (avec l’accord d’un adulte), photographier un même sujet en gros plan puis en plan large ; sinon, dessiner les deux cadrages d’après un sujet observé.','20 minutes.','Un appareil photo ou smartphone (facultatif), ou papier et crayon.','Demander l’accord des personnes photographiées avant toute prise de vue.','Les deux cadrages donnent-ils des informations différentes sur le sujet ? Lequel préférez-vous et pourquoi ?')],
  [{q:'Compare une photo d’un enfant prise en contre-plongée (vue du dessous) et une photo prise en plongée (vue du dessus).',s:['La contre-plongée donne une impression de grandeur à l’enfant photographié.','La plongée donne au contraire une impression de domination sur l’enfant.','Le choix d’angle transforme fortement la perception du même sujet.']}],
  ['Je distingue gros plan, plan rapproché et plan large.','Je comprends l’effet de la plongée et de la contre-plongée.','Je connais le principe de la règle des tiers.','Je comprends l’importance du moment précis de la prise de vue.'],
  ['Confondre plongée et contre-plongée.','Ignorer l’effet du choix de plan sur la perception du sujet.','Photographier une personne sans lui demander son accord.'],
  ['Plan (gros plan, plan large) et angle (plongée, contre-plongée).','Règle des tiers : composition équilibrée.','Instant décisif : moment précis du déclenchement.']),
 g:mix([pairs([['la plongée','une vue du dessus, qui donne une impression de domination sur le sujet'],['la contre-plongée','une vue du dessous, qui donne une impression de puissance ou de grandeur']],{q:'%s désigne…',rq:'Quel angle de vue correspond à : %s ?'}),2],
  [bank([
   ['Un gros plan montre…','un sujet de très près, avec peu d’éléments de contexte',['uniquement un paysage très large','uniquement un groupe nombreux de personnes','uniquement un objet flou'],'Il concentre l’attention sur un détail précis.'],
   ['Un plan large montre…','le sujet avec beaucoup d’éléments du contexte environnant',['uniquement le visage d’une personne','uniquement un détail microscopique','rien du tout'],'Il situe le sujet dans son environnement.'],
   ['La règle des tiers consiste à…','diviser l’image en trois bandes horizontales et verticales pour placer le sujet',['centrer toujours strictement le sujet','ignorer totalement la composition','utiliser uniquement des couleurs vives'],'Elle aide à obtenir une composition équilibrée.'],
   ['Photographier une personne sans lui demander son accord respecte-t-il son droit à l’image ?','non',['oui, toujours','oui, si la photo est jolie','oui, en toutes circonstances'],'L’accord de la personne photographiée est nécessaire.'],
   {tf:'Un même sujet photographié avec des cadrages différents peut donner des impressions très différentes.',v:true,e:'Le cadrage transforme fortement la perception d’une scène.'},
   {tf:'La contre-plongée (vue du dessous) donne généralement une impression de faiblesse au sujet photographié.',v:false,e:'Elle donne au contraire souvent une impression de puissance ou de grandeur.',d:2},
  ['L’instant décisif, en photographie, désigne…','le moment précis choisi pour déclencher la prise de vue',['la durée totale de la séance photo','uniquement le réglage de la couleur','le prix de l’appareil utilisé'],'Ce choix de moment capte souvent un mouvement ou une expression particulière.'],
  ['Un plan rapproché, intermédiaire entre le gros plan et le plan large, montre généralement…','le sujet avec un peu de son environnement proche',['uniquement un détail microscopique','uniquement un paysage très large sans aucun sujet','rien de reconnaissable'],'Il offre un compromis entre proximité et contexte.']]),2])},

{id:'arts5e',name:'Objet artistique, design et usage',icon:'🪑',domain:'Objet',
 refs:[BO,EDU],
 tip:'Un objet de design réussi combine généralement une fonction pratique (son usage) et une recherche esthétique (son apparence) : les deux dimensions s’articulent ensemble.',
 c:C(`Le <b>design</b> conçoit des objets qui allient <b>fonction</b> pratique (leur usage) et <b>esthétique</b> (leur apparence), à la différence d’une œuvre d’art qui n’a pas forcément de fonction pratique.`,
  [T('Fonction et forme',`<p>Un objet de design doit d’abord répondre à une <b>fonction</b> : une chaise doit permettre de s’asseoir confortablement, une lampe doit éclairer efficacement. La <b>forme</b> choisie (ergonomie, matériaux, couleurs) doit servir cette fonction tout en étant esthétiquement pensée : « la forme suit la fonction » est un principe souvent cité en design.</p>`),
   T('Design et art : une frontière parfois floue',`<p>La frontière entre un <b>objet design</b> (pensé pour un usage) et une <b>œuvre d’art</b> (sans fonction pratique nécessaire) n’est pas toujours nette : certains objets de design sont exposés dans des musées pour leur qualité esthétique, et certaines œuvres d’art s’inspirent directement d’objets fonctionnels du quotidien.</p>`),
   HE('Concevoir le croquis d’un objet design répondant à un besoin précis.','Choisir un besoin simple (ranger des crayons, porter un livre) et dessiner le croquis d’un objet qui y répond, en pensant à sa forme et ses matériaux.','20 minutes.','Papier, crayon.','Aucun matériel dangereux dans cet atelier.','Mon objet répond-il clairement au besoin identifié ? Ai-je réfléchi à la fois à la fonction et à l’esthétique ?')],
  [{q:'Conçois le croquis d’une lampe de bureau design.',s:['Fonction : éclairer efficacement une surface de travail.','Forme : un bras orientable pour diriger la lumière où on le souhaite.','Esthétique : des matériaux et des couleurs qui s’accordent avec un bureau moderne.']}],
  ['Je sais ce qu’est le design (fonction + esthétique).','Je comprends le principe « la forme suit la fonction ».','Je sais que la frontière entre design et art n’est pas toujours nette.','Je sais concevoir un objet simple répondant à un besoin précis.'],
  ['Confondre design et œuvre d’art sans aucune fonction pratique.','Concevoir un objet sans réfléchir à sa fonction réelle.','Ignorer l’aspect esthétique au profit de la seule fonction.'],
  ['Design = fonction + esthétique.','« La forme suit la fonction. »','Frontière design/art parfois floue.']),
 g:mix([bank([
  ['Le design conçoit des objets qui combinent principalement…','une fonction pratique et une recherche esthétique',['uniquement une fonction, sans aucune esthétique','uniquement une esthétique, sans aucune fonction','aucune des deux dimensions'],'Les deux aspects s’articulent dans un bon objet de design.'],
  ['Le principe « la forme suit la fonction » signifie que…','la forme d’un objet doit d’abord servir son usage',['la fonction n’a jamais aucune importance','la forme doit toujours ignorer l’usage','la fonction et la forme n’ont jamais aucun lien'],'C’est un principe fréquemment cité en design.'],
  ['Une œuvre d’art a-t-elle toujours une fonction pratique, comme un objet de design ?','non, elle n’a pas forcément de fonction pratique',['oui, toujours une fonction pratique précise','oui, systématiquement, sans exception','oui, comme tout objet de design'],'C’est souvent ce qui distingue l’art du design, même si la frontière reste parfois floue.'],
  ['Certains objets de design sont-ils parfois exposés dans des musées pour leur qualité esthétique ?','oui, certains objets de design ont une reconnaissance artistique',['non, jamais','non, les musées n’exposent que de la peinture','non, cela est toujours interdit'],'La frontière entre design et art n’est pas toujours stricte.',2],
  {tf:'Un objet de design doit généralement répondre à un usage précis.',v:true,e:'C’est l’une de ses caractéristiques principales.'},
  {tf:'L’esthétique n’a jamais aucune importance dans la conception d’un objet de design.',v:false,e:'Elle est au contraire souvent pensée avec soin, en complément de la fonction.',d:2},
  ['Le choix des matériaux d’un objet de design peut-il influencer à la fois sa fonction et son esthétique ?','oui, un matériau influence la résistance, le poids et l’apparence',['non, le matériau n’a jamais aucun effet','non, cela ne concerne que la couleur','non, un matériau est toujours neutre sur l’usage'],'Le matériau choisi a des conséquences pratiques et visuelles.'],
  ['Concevoir un objet pour qu’il soit facile et confortable à utiliser relève d’une préoccupation…','ergonomique',['uniquement décorative','sans aucun lien avec le design','uniquement économique'],'L’ergonomie vise le confort d’usage.'],
  ['Un designer peut-il s’inspirer de formes naturelles (comme une coquille ou une feuille) pour concevoir un objet ?','oui, la nature est une source d’inspiration fréquente en design',['non, jamais','non, cela est toujours interdit','non, le design ignore toujours la nature'],'De nombreux objets de design s’inspirent de formes organiques.'],
  ['Un même objet (par exemple une chaise) peut-il exister en de nombreuses versions différentes selon les choix de design ?','oui, forme, matériau et fonction précise peuvent varier fortement',['non, une chaise a toujours exactement la même forme','non, le design ne produit jamais de variation','non, tous les objets d’un même usage sont toujours identiques'],'La diversité des réponses possibles à un même besoin est une richesse du design.'],
  ['Un objet de design peut-il être pensé pour être facilement réparé ou recyclé en fin de vie ?','oui, cette préoccupation est de plus en plus présente dans le design contemporain',['non, cela n’a jamais été une préoccupation du design','non, le design ignore toujours la fin de vie des objets','non, cela concerne uniquement l’architecture'],'Le design intègre de plus en plus des enjeux environnementaux.',2],
  ['Un objet mal conçu, difficile et inconfortable à utiliser malgré une belle apparence, est-il un bon exemple de design réussi ?','non, la fonction pratique reste essentielle, même avec une belle apparence',['oui, l’apparence suffit toujours à elle seule','oui, le confort d’usage n’a jamais aucune importance','oui, le design ignore toujours la fonction pratique'],'Un bon design articule fonction et esthétique, sans sacrifier l’une à l’autre.']]),2])},

{id:'arts5f',name:'Analyser une œuvre et argumenter',icon:'🔎',domain:'Culture artistique',
 refs:[BO,EDU],
 tip:'Pour analyser une œuvre en arts plastiques, observe d’abord les choix techniques (couleurs, formes, composition) avant d’interpréter leur effet ou leur signification possible.',
 c:C(`Analyser une œuvre en arts plastiques demande d’observer précisément les <b>choix</b> faits par l’artiste (techniques, composition, couleurs) et d’en proposer une <b>interprétation</b> argumentée.`,
  [T('Observer les choix techniques',`<p>On repère d’abord les choix concrets : quelles <b>couleurs</b> sont utilisées (chaudes, froides, contrastées) ? quelle <b>composition</b> (symétrique, asymétrique) ? quelles <b>formes</b> (géométriques, organiques) ? quelle <b>texture</b> apparente ? Ces observations précises sont la base de toute analyse.</p>`),
   T('Interpréter avec des arguments',`<p>À partir de ces observations, on peut proposer une <b>interprétation</b> : quel effet ces choix produisent-ils ? quelle intention peut-on supposer chez l’artiste ? Chaque interprétation doit être <b>justifiée</b> par un élément précis observé dans l’œuvre, plutôt que d’être une simple impression sans fondement.</p>`),
   HE('Analyser une reproduction d’œuvre étudiée en classe en reliant observation et interprétation.','Choisir une œuvre étudiée récemment et rédiger 3 phrases : une observation de couleur, une observation de composition, puis une interprétation justifiée par ces observations.','20 minutes.','La reproduction d’une œuvre étudiée, un support pour écrire.','Aucun matériel dangereux dans cet atelier.','Mes observations sont-elles précises ? Mon interprétation s’appuie-t-elle clairement sur ces observations ?')],
  [{q:'Analyse un tableau utilisant des couleurs froides et une composition asymétrique.',s:['Observation : couleurs froides (bleus, verts) dominantes.','Observation : composition asymétrique, sujet décalé sur le côté.','Interprétation : ces choix peuvent suggérer une ambiance calme mais légèrement tendue.']}],
  ['Je sais observer précisément les choix techniques d’une œuvre (couleurs, composition, formes).','Je sais proposer une interprétation à partir de ces observations.','Je sais justifier mon interprétation par un élément précis observé.','Je distingue une impression sans fondement d’une interprétation argumentée.'],
  ['Interpréter une œuvre sans aucune observation précise pour la justifier.','Se limiter à décrire sans jamais proposer d’interprétation.','Confondre impression personnelle non justifiée et interprétation argumentée.'],
  ['Observer : couleurs, composition, formes, texture.','Interpréter : effet, intention supposée.','Justifier chaque interprétation par une observation précise.']),
 g:mix([bank([
  ['La première étape pour analyser une œuvre en arts plastiques est…','observer précisément les choix techniques utilisés',['donner immédiatement un avis sans aucune observation','ignorer totalement la composition','juger uniquement si l’œuvre est belle ou non'],'L’observation précise fonde toute interprétation rigoureuse.'],
  ['Une interprétation d’œuvre doit-elle être justifiée par un élément précis observé ?','oui, sinon ce n’est qu’une impression non argumentée',['non, aucune justification n’est jamais nécessaire','non, l’interprétation est toujours évidente sans preuve','non, seule l’intuition compte'],'La justification rend l’analyse plus rigoureuse.'],
  ['Observer qu’une œuvre utilise des couleurs froides et une composition asymétrique permet de…','proposer une interprétation argumentée sur l’ambiance suggérée',['remplacer totalement l’interprétation','rendre toute interprétation impossible','ignorer l’effet de l’œuvre'],'Ces observations nourrissent une interprétation fondée.'],
  ['Dire seulement « j’aime » ou « je n’aime pas » une œuvre constitue-t-il une analyse argumentée ?','non, un simple goût personnel n’est pas une analyse',['oui, cela suffit toujours','oui, c’est la meilleure méthode d’analyse','oui, aucune autre justification n’est jamais nécessaire'],'Une analyse argumentée repose sur des observations précises.'],
  {tf:'Observer les choix de couleurs et de composition aide à construire une interprétation argumentée.',v:true,e:'L’observation précise est la base de l’analyse.'},
  {tf:'Une interprétation d’œuvre n’a jamais besoin d’être reliée à une observation précise.',v:false,e:'Au contraire, elle doit s’appuyer sur des éléments observés dans l’œuvre.',d:2},
  ['Comparer une œuvre étudiée à une autre œuvre connue peut-il enrichir une analyse argumentée ?','oui, la comparaison aide souvent à préciser une interprétation',['non, cela n’apporte jamais rien','non, chaque œuvre doit toujours être analysée isolément, sans aucun lien','non, la comparaison rend toujours l’analyse confuse'],'Mettre en relation plusieurs œuvres éclaire souvent leurs choix respectifs.'],
  ['Relier le contexte de création d’une œuvre (époque, lieu) à son analyse peut-il renforcer l’interprétation proposée ?','oui, le contexte éclaire souvent les choix faits par l’artiste',['non, le contexte n’a jamais aucune utilité','non, il faut toujours ignorer le contexte de création','non, le contexte complique toujours inutilement l’analyse'],'Le contexte historique et artistique nourrit souvent l’interprétation.'],
  ['Une analyse qui ne mentionne que le titre de l’œuvre, sans aucune observation du contenu, est-elle suffisante ?','non, elle doit s’appuyer sur une observation précise du contenu',['oui, le titre seul suffit toujours','oui, c’est la meilleure méthode d’analyse','oui, aucune observation n’est jamais nécessaire'],'L’analyse doit porter sur ce qui est effectivement visible dans l’œuvre.'],
  ['Deux élèves peuvent-ils proposer des interprétations légèrement différentes d’une même œuvre, tout en restant pertinentes ?','oui, si chacune s’appuie sur des observations précises et justifiées',['non, une seule interprétation est toujours possible','non, toute différence d’interprétation est toujours une erreur','non, l’interprétation est toujours identique pour tout le monde'],'Plusieurs interprétations argumentées peuvent coexister autour d’une même œuvre.'],
  ['Observer la taille réelle d’une œuvre (très grande ou très petite) peut-il faire partie d’une analyse rigoureuse ?','oui, la taille influence souvent la perception et l’impact de l’œuvre',['non, la taille n’a jamais aucune importance','non, seule la couleur compte dans une analyse','non, la taille concerne uniquement l’architecture'],'Les dimensions réelles d’une œuvre participent à l’expérience du spectateur.'],
  ['Reformuler une interprétation après avoir observé un détail d’une œuvre qu’on n’avait pas remarqué au départ est-il un signe de rigueur ?','oui, ajuster son interprétation selon de nouvelles observations est une démarche honnête',['non, il faut toujours garder sa première impression sans jamais la changer','non, changer d’avis est toujours un signe de faiblesse','non, les détails nouveaux n’ont jamais aucune importance'],'La rigueur inclut la capacité à affiner son analyse.']]),2])}
]);

MQ.add('arts','4',[
{id:'arts4a',name:'Représentation, ressemblance et écart',icon:'🎭',domain:'Représentation',
 refs:[BO,EDU],
 tip:'Un écart volontaire avec la ressemblance exacte (une déformation, une simplification) peut renforcer l’expression d’une œuvre plutôt que l’affaiblir.',
 c:C(`Représenter un sujet ne signifie pas toujours chercher une <b>ressemblance</b> exacte : un <b>écart</b> volontaire avec le réel peut servir une intention artistique.`,
  [T('Ressemblance et fidélité',`<p>La <b>ressemblance</b> cherche à reproduire fidèlement l’apparence d’un sujet (un portrait réaliste, par exemple). Cette fidélité demande une observation précise des proportions, des couleurs et des détails du modèle représenté.</p>`),
   T('L’écart volontaire',`<p>Un artiste peut volontairement s’<b>écarter</b> de la ressemblance exacte : <b>déformer</b> des proportions, <b>simplifier</b> des formes, <b>exagérer</b> certains détails. Cet écart n’est pas une erreur : il peut renforcer une émotion, une idée, ou créer un style reconnaissable. Le cubisme (étudié en histoire des arts) illustre un écart radical avec la ressemblance traditionnelle.</p>`),
   HE('Réaliser un portrait en deux versions : ressemblant puis volontairement déformé.','Dessiner un visage simple en cherchant d’abord la ressemblance, puis le redessiner en exagérant volontairement un ou plusieurs traits.','30 minutes.','Papier, crayon ou feutres.','Aucun matériel dangereux.','Les deux versions sont-elles bien différentes ? La déformation volontaire change-t-elle l’expression ou l’effet du portrait ?')],
  [{q:'Compare un portrait réaliste et un portrait aux traits exagérés (grands yeux, sourire large).',s:['Le portrait réaliste cherche la fidélité aux proportions du modèle.','Le portrait aux traits exagérés s’écarte volontairement de la ressemblance exacte.','Cet écart peut renforcer une expression ou une émotion particulière.']}],
  ['Je sais ce que signifie chercher la ressemblance dans une représentation.','Je sais qu’un écart avec la ressemblance peut être volontaire.','Je comprends qu’une déformation peut renforcer une intention artistique.','Je connais un exemple de mouvement artistique qui s’écarte de la ressemblance (le cubisme).'],
  ['Croire qu’un écart avec la ressemblance est toujours une erreur de l’artiste.','Confondre déformation volontaire et maladresse technique.','Ignorer que la simplification peut aussi être un choix artistique.'],
  ['Ressemblance = fidélité au modèle.','Écart volontaire = déformation, simplification, exagération.','L’écart peut renforcer une intention artistique.']),
 g:mix([sort({'Recherche de ressemblance':['reproduire fidèlement les proportions d’un visage','respecter précisément les couleurs observées sur le modèle'],'Écart volontaire':['exagérer la taille des yeux pour accentuer une émotion','simplifier un corps en quelques formes géométriques simples']},{q:'« %s » relève de…'}),2],
  [bank([
   ['Chercher la ressemblance dans une représentation signifie…','reproduire fidèlement l’apparence du modèle',['déformer systématiquement toutes les proportions','ignorer totalement le modèle','utiliser uniquement des couleurs imaginaires'],'Cela demande une observation précise.'],
   ['Un écart volontaire avec la ressemblance exacte est-il toujours une erreur ?','non, il peut être un choix artistique délibéré',['oui, toujours une erreur','oui, c’est systématiquement un manque de technique','oui, cela ne se produit jamais chez un artiste reconnu'],'De nombreux artistes choisissent volontairement de s’écarter du réel.'],
   ['Exagérer certains détails d’un visage (grands yeux, sourire large) peut servir à…','renforcer une expression ou une émotion',['toujours rendre l’image incompréhensible','remplacer totalement le sujet représenté','être uniquement une erreur technique'],'L’exagération peut intensifier un effet recherché.'],
   ['Le cubisme illustre un écart avec la ressemblance traditionnelle en…','représentant un sujet selon plusieurs points de vue combinés',['copiant exactement la réalité observée','évitant toute déformation des formes','utilisant uniquement des couleurs réalistes'],'C’est un exemple étudié en histoire des arts.',2],
   {tf:'Simplifier un sujet en quelques formes géométriques peut être un choix artistique volontaire.',v:true,e:'La simplification n’est pas forcément un manque de compétence.'},
   {tf:'Un portrait réaliste ne demande aucune observation précise du modèle.',v:false,e:'Il demande au contraire une observation attentive des proportions et détails.',d:2},
  ['Simplifier un corps humain en quelques formes géométriques de base (cercles, rectangles) relève…','d’un écart volontaire avec la ressemblance détaillée',['toujours d’une impossibilité technique de l’artiste','d’une recherche exacte de ressemblance','d’une erreur à corriger systématiquement'],'La simplification peut être un choix esthétique assumé.'],
  ['Un même modèle dessiné par deux élèves différents donnera-t-il nécessairement deux dessins identiques ?','non, chaque regard et chaque geste produisent un résultat différent',['oui, toujours rigoureusement identiques','oui, car il n’existe qu’une seule façon de représenter un modèle','oui, sauf en cas d’erreur technique'],'La représentation reste une interprétation personnelle du modèle observé.']]),2])},

{id:'arts4b',name:'Espace réel, espace représenté',icon:'📏',domain:'Espace',
 refs:[BO,EDU],
 tip:'L’espace réel (où se trouve physiquement une œuvre, comme une sculpture) est différent de l’espace représenté (l’illusion de profondeur suggérée sur une surface plane, comme une peinture).',
 c:C(`On distingue l’<b>espace réel</b> dans lequel une œuvre existe physiquement de l’<b>espace représenté</b>, qui est l’illusion d’espace suggérée par l’œuvre elle-même.`,
  [T('Espace réel',`<p>L’<b>espace réel</b> est l’espace physique concret dans lequel une œuvre existe : une sculpture occupe un volume réel, une installation occupe une pièce entière. Le spectateur peut se déplacer physiquement autour ou dans cet espace réel.</p>`),
   T('Espace représenté',`<p>L’<b>espace représenté</b> est l’illusion d’espace suggérée par une œuvre plane (un dessin, une peinture) : la perspective, les plans, les ombres créent une impression de profondeur qui n’existe pas physiquement sur la surface plane du support. Certaines œuvres jouent sur l’écart entre ces deux espaces, par exemple des dessins en trompe-l’œil qui semblent sortir de leur support.</p>`),
   HE('Créer un dessin en trompe-l’œil simple jouant sur l’écart entre espace réel et représenté.','Dessiner un objet simple (une boîte, un escalier) en essayant de créer une illusion de profondeur qui donne envie de toucher pour vérifier si c’est plat.','30 minutes.','Papier, crayon.','Aucun matériel dangereux.','Mon dessin donne-t-il une impression de profondeur convaincante ? L’écart entre la surface plane réelle et l’espace représenté est-il perceptible ?')],
  [{q:'Compare une sculpture exposée dans une salle et une peinture représentant un paysage.',s:['La sculpture occupe un espace réel : le spectateur peut en faire le tour.','La peinture suggère un espace représenté : une illusion de profondeur sur une surface plane.','Ces deux types d’espace fonctionnent de façon très différente.']}],
  ['Je distingue espace réel et espace représenté.','Je sais qu’une sculpture occupe un espace réel observable sous plusieurs angles.','Je sais qu’une peinture suggère un espace représenté, illusion sur une surface plane.','Je connais le principe du trompe-l’œil.'],
  ['Confondre espace réel (physique) et espace représenté (illusion sur une surface plane).','Croire qu’une sculpture ne peut être observée que de face, comme une peinture.','Ignorer que le trompe-l’œil joue sur l’écart entre surface plane et illusion de profondeur.'],
  ['Espace réel : physique, occupé par l’œuvre.','Espace représenté : illusion suggérée sur une surface plane.','Trompe-l’œil : jeu sur cet écart.']),
 g:mix([sort({'Espace réel':['le volume occupé par une statue dans une salle','la pièce entière occupée par une installation'],'Espace représenté':['la profondeur suggérée par la perspective d’une peinture','l’illusion d’un couloir qui s’éloigne, dessinée sur une feuille plate']},{q:'« %s » relève de l’espace…'}),2],
  [bank([
   ['L’espace réel d’une œuvre désigne…','l’espace physique concret qu’elle occupe',['uniquement une illusion visuelle','uniquement une suggestion de profondeur sur une surface plane','un espace qui n’existe jamais vraiment'],'Une sculpture occupe un espace réel observable physiquement.'],
   ['L’espace représenté désigne…','l’illusion de profondeur suggérée sur une surface plane',['l’espace physique réellement occupé par l’œuvre','uniquement la taille du support utilisé','un espace qui n’a jamais aucun rapport avec l’œuvre'],'Une peinture suggère cet espace sans qu’il existe physiquement.'],
   ['Un trompe-l’œil joue sur…','l’écart entre une surface plane réelle et une illusion de profondeur',['l’absence totale d’illusion','uniquement la couleur utilisée','uniquement la taille du support'],'Il cherche à tromper la perception du spectateur.'],
   ['Peut-on se déplacer physiquement autour d’une sculpture pour l’observer sous plusieurs angles ?','oui, car elle occupe un espace réel',['non, jamais','non, une sculpture se regarde toujours uniquement de face','non, cela n’a aucun lien avec l’espace réel'],'C’est une caractéristique de l’espace réel occupé par une œuvre en volume.'],
   {tf:'Une peinture représentant un paysage suggère un espace qui n’existe pas physiquement sur sa surface.',v:true,e:'C’est le principe même de l’espace représenté.'},
   {tf:'Une installation occupant une pièce entière relève de l’espace représenté, et non de l’espace réel.',v:false,e:'Elle occupe au contraire un espace réel, physique.',d:2},
  ['Un dessin en perspective peut-il donner l’impression qu’un couloir s’éloigne, alors que le support reste plat ?','oui, c’est le principe même de l’espace représenté par la perspective',['non, un dessin ne peut jamais suggérer une telle impression','non, seule une sculpture pourrait le faire','non, cela nécessite toujours un support non plat'],'La perspective crée une illusion de profondeur sur une surface plane.'],
  ['Une installation qui invite le spectateur à marcher à l’intérieur de l’œuvre joue-t-elle avec l’espace réel ?','oui, le spectateur se déplace physiquement dans cet espace',['non, cela reste toujours un espace uniquement représenté','non, le spectateur ne peut jamais entrer dans une œuvre','non, cela n’a aucun lien avec l’espace réel'],'L’installation transforme l’espace réel en expérience vécue par le spectateur.']]),2])},

{id:'arts4c',name:'Image fixe, image animée et montage',icon:'🎬',domain:'Image',
 refs:[BO,EDU],
 tip:'Le montage choisit l’ordre, la durée et l’enchaînement des plans d’une vidéo : deux montages différents à partir des mêmes images peuvent raconter des histoires très différentes.',
 c:C(`Une <b>image animée</b> (vidéo, film d’animation) ajoute le <b>mouvement</b> et le <b>temps</b> à l’image fixe, et le <b>montage</b> permet d’organiser cette succession d’images pour construire un sens.`,
  [T('De l’image fixe à l’image animée',`<p>Une <b>image fixe</b> capture un seul instant. Une <b>image animée</b> est constituée d’une succession rapide d’images fixes (appelées <b>images par seconde</b>) qui, projetées rapidement, créent l’illusion du mouvement grâce à la <b>persistance rétinienne</b> de notre œil.</p>`),
   T('Le montage',`<p>Le <b>montage</b> consiste à choisir l’<b>ordre</b>, la <b>durée</b> et l’<b>enchaînement</b> des plans d’une vidéo. Un même ensemble de plans peut être monté de façons très différentes, racontant des histoires différentes ou créant des ambiances différentes (rythme rapide et nerveux, ou lent et contemplatif).</p>`),
   HE('Imaginer un montage simple à partir de 4 images fixes dessinées ou choisies.','Dessiner ou choisir 4 images représentant des étapes d’une action, puis déterminer leur ordre de montage pour raconter une histoire claire.','20 minutes.','Papier, crayon, ou images imprimées.','Aucun matériel dangereux.','L’ordre choisi raconte-t-il une histoire claire et compréhensible ? Un autre ordre aurait-il changé le sens de l’histoire ?')],
  [{q:'Explique comment le montage peut changer le sens d’une même série de plans.',s:['Le même plan d’un personnage souriant peut être monté après un plan triste ou après un plan joyeux.','Selon l’ordre choisi, le sourire sera interprété différemment (ironique ou sincère).','Le montage construit donc une partie importante du sens d’une vidéo.']}],
  ['Je comprends le principe de la persistance rétinienne dans l’image animée.','Je sais ce qu’est un plan dans une vidéo.','Je comprends que le montage choisit ordre, durée et enchaînement des plans.','Je comprends qu’un même ensemble de plans peut être monté différemment pour créer des effets différents.'],
  ['Croire qu’une image animée n’est qu’une suite d’images fixes sans aucune illusion de mouvement.','Ignorer que le montage influence fortement le sens d’une vidéo.','Penser qu’un seul montage possible existe pour un ensemble donné de plans.'],
  ['Image animée = succession rapide d’images fixes (persistance rétinienne).','Montage : ordre, durée, enchaînement des plans.','Un même matériau peut être monté différemment.']),
 g:mix([bank([
  ['Une image animée crée l’illusion du mouvement grâce à…','la persistance rétinienne de l’œil face à une succession rapide d’images',['la seule couleur utilisée','la taille de l’écran','le nombre de spectateurs présents'],'Notre œil « retient » brièvement chaque image, créant une impression de continuité.'],
  ['Le montage d’une vidéo consiste à choisir…','l’ordre, la durée et l’enchaînement des plans',['uniquement la musique de fond','uniquement le titre de la vidéo','uniquement la couleur de l’image'],'Ces choix influencent fortement le sens final de la vidéo.'],
  ['Un même ensemble de plans peut-il être monté de plusieurs façons différentes, racontant des histoires différentes ?','oui',['non, un seul montage possible existe toujours','non, l’ordre n’a jamais aucune importance','non, le montage ne change jamais le sens'],'Le montage est un outil narratif puissant.'],
  ['Un rythme de montage rapide, avec des plans très courts, crée souvent une ambiance…','nerveuse ou dynamique',['toujours calme et lente','toujours identique à un montage lent','sans aucun effet particulier'],'La durée des plans influence fortement le ressenti.'],
  {tf:'Le montage peut changer le sens ou l’ambiance d’une vidéo, même à partir des mêmes plans de départ.',v:true,e:'C’est l’un des pouvoirs essentiels du montage.'},
  {tf:'Une image animée n’a aucun lien avec une succession d’images fixes.',v:false,e:'Elle est justement constituée d’une succession rapide d’images fixes.',d:2},
  ['Un film d’animation réalisé image par image (stop motion) demande généralement…','de photographier de nombreuses petites variations de position d’un objet ou d’une figurine',['une seule photographie suffisante pour toute l’animation','aucune photographie, seulement du dessin direct','un enregistrement vidéo continu sans aucune photo'],'Chaque petit déplacement est photographié séparément.',2],
  ['Choisir de couper un plan juste avant la fin d’une action, plutôt que de montrer l’action jusqu’au bout, relève…','d’un choix de montage qui peut créer du suspense ou de la surprise',['d’une erreur systématique de montage','d’une impossibilité technique','d’un hasard sans aucune intention'],'Le moment précis de la coupe est un choix narratif du monteur.'],
  ['La bande sonore (musique, bruitages) ajoutée lors du montage peut-elle influencer l’interprétation d’une scène ?','oui, elle participe fortement à l’ambiance et au sens perçus',['non, le son n’a jamais aucune influence','non, seule l’image compte dans un montage','non, le son est toujours ajouté au hasard'],'Son et image se combinent pour construire le sens d’une vidéo.'],
  ['Un fondu qui fait disparaître progressivement une image pour en révéler une autre est une technique de…','transition entre deux plans lors du montage',['tournage uniquement, sans aucun lien avec le montage','photographie fixe uniquement','sculpture'],'Les transitions font partie des outils disponibles au montage.',2],
  ['Alterner des plans de deux personnages qui se répondent (champ-contrechamp) est une technique fréquente pour monter…','un dialogue entre deux personnages',['un paysage immobile uniquement','une seule image fixe sans aucun montage','une sculpture en volume'],'Elle permet de suivre l’échange entre les deux interlocuteurs.',3],
  ['Le choix de garder un plan long, sans coupure, plutôt que de multiplier les coupes rapides, peut-il créer une ambiance particulière ?','oui, cela peut donner une impression de temps réel ou de contemplation',['non, un plan long n’a jamais aucun effet particulier','non, il faut toujours couper très souvent pour obtenir un effet','non, la durée d’un plan n’a jamais d’importance'],'La durée d’un plan participe au rythme et à l’ambiance générale.',2]]),2])},

{id:'arts4d',name:'Matérialité de l’œuvre',icon:'🧱',domain:'Matière',
 refs:[BO,EDU],
 tip:'Un même sujet (par exemple un visage) rendu en marbre, en papier déchiré ou en pixels numériques produira des effets très différents, liés à la matière utilisée.',
 c:C(`La <b>matérialité</b> d’une œuvre désigne les qualités physiques de la <b>matière</b> utilisée (texture, poids, transparence, fragilité), qui influencent fortement la perception de l’œuvre, indépendamment du sujet représenté.`,
  [T('Les qualités de la matière',`<p>Chaque matière a des qualités propres : le <b>marbre</b> est lourd, lisse, durable ; le <b>papier</b> est léger, fragile, parfois translucide ; le <b>métal</b> peut être brillant ou rouillé. Ces qualités influencent l’impression donnée par une œuvre, même si le sujet représenté reste identique.</p>`),
   T('Du réel au numérique',`<p>Une œuvre peut exister dans une matière <b>physique</b> (pierre, bois, toile) ou être entièrement <b>numérique</b> (composée de pixels, sans matière physique propre). Une œuvre numérique pose des questions différentes : elle peut être reproduite à l’identique indéfiniment, contrairement à une œuvre physique unique.</p>`),
   HE('Réaliser une même forme simple dans deux matières différentes et comparer.','Réaliser une même forme simple (par exemple une étoile) une fois en papier découpé, une fois en pâte à modeler ou argile si disponible, et comparer les deux résultats.','30 minutes.','Papier, ciseaux, pâte à modeler ou argile si disponible.','Utiliser les ciseaux avec précaution.','Les deux matières donnent-elles des impressions différentes pour la même forme ? Quelles qualités (poids, texture) ont changé ?')],
  [{q:'Compare une sculpture en marbre et la même forme réalisée en papier froissé.',s:['Le marbre donne une impression de solidité, de poids et de durabilité.','Le papier froissé donne une impression de légèreté et de fragilité.','La matière utilisée transforme fortement la perception de la même forme.']}],
  ['Je sais que la matière utilisée influence la perception d’une œuvre.','Je connais des qualités propres à différentes matières (marbre, papier, métal).','Je comprends la différence entre une œuvre physique et une œuvre numérique.','Je sais qu’une œuvre numérique peut être reproduite indéfiniment, contrairement à une œuvre physique unique.'],
  ['Croire que la matière utilisée n’a aucune influence sur la perception d’une œuvre.','Confondre les qualités du marbre et celles du papier.','Ignorer la différence entre une œuvre physique unique et une œuvre numérique reproductible.'],
  ['Matérialité : qualités physiques de la matière (texture, poids, fragilité).','Même sujet, matières différentes = effets différents.','Œuvre physique unique vs œuvre numérique reproductible.']),
 g:mix([sort({'Qualité associée au marbre':['la solidité et le poids','la durabilité dans le temps'],'Qualité associée au papier':['la légèreté','la fragilité']},{q:'« %s » est une qualité plutôt associée…'}),2],
  [bank([
   ['La matérialité d’une œuvre désigne…','les qualités physiques de la matière utilisée',['uniquement le sujet représenté','uniquement la signature de l’artiste','uniquement le prix de l’œuvre'],'Texture, poids, fragilité en font partie.'],
   ['Une même forme réalisée en marbre et en papier produit-elle la même impression ?','non, les qualités de chaque matière influencent la perception',['oui, exactement la même impression','oui, la matière n’a jamais aucun effet','oui, car seule la forme compte'],'Poids, texture et durabilité diffèrent selon la matière.'],
   ['Une œuvre numérique, contrairement à une œuvre physique unique, peut généralement…','être reproduite à l’identique de nombreuses fois',['jamais être copiée','être détruite uniquement une fois','exister uniquement sous forme physique'],'Cette reproductibilité pose des questions différentes de celles d’une œuvre physique unique.'],
   ['Le papier, comme matière, est souvent associé à…','la légèreté et parfois la fragilité',['la lourdeur extrême et la solidité absolue','l’impossibilité totale de le découper','une transparence totale systématique'],'Ces qualités influencent les œuvres réalisées avec ce matériau.'],
   {tf:'La matière utilisée dans une œuvre influence la perception, indépendamment du sujet représenté.',v:true,e:'Les qualités physiques de la matière jouent un rôle propre.'},
   {tf:'Une œuvre numérique a exactement les mêmes propriétés physiques qu’une œuvre en pierre.',v:false,e:'Une œuvre numérique n’a pas de matière physique propre, contrairement à une sculpture en pierre.',d:2},
  ['Le verre, comme matière, apporte souvent une qualité de…','transparence ou de fragilité',['opacité totale et lourdeur extrême','souplesse infinie comme un tissu','chaleur extrême au toucher'],'Sa transparence influence fortement les œuvres qui l’utilisent.'],
  ['Une œuvre réalisée avec des matériaux qui se dégradent avec le temps (fleurs, glace) pose-t-elle une question particulière sur sa conservation ?','oui, son caractère éphémère interroge la durée de vie de l’œuvre',['non, aucune question particulière ne se pose jamais','non, ces matériaux durent toujours indéfiniment','non, cela ne concerne que la sculpture en marbre'],'Certaines démarches artistiques assument volontairement ce caractère éphémère.',2]]),2])},

{id:'arts4e',name:'Architecture, design et environnement',icon:'🏢',domain:'Design',
 refs:[BO,EDU],
 tip:'Un projet d’architecture ou de design responsable prend en compte son impact sur l’environnement : matériaux utilisés, énergie consommée, intégration dans le paysage.',
 c:C(`L’architecture et le design contemporains s’interrogent de plus en plus sur leur relation à l’<b>environnement</b>, en intégrant des préoccupations écologiques dans leurs projets.`,
  [T('Penser l’impact environnemental',`<p>Concevoir un bâtiment ou un objet demande de penser aux <b>matériaux</b> utilisés (renouvelables ou non), à l’<b>énergie</b> nécessaire pour le fabriquer et le faire fonctionner, et à son impact sur le <b>paysage</b> environnant. Ces préoccupations rejoignent celles étudiées en histoire des arts sur l’architecture contemporaine durable.</p>`),
   T('S’intégrer au paysage',`<p>Un projet peut chercher à s’<b>intégrer harmonieusement</b> dans son environnement (formes, couleurs, matériaux qui rappellent le paysage local) ou, au contraire, à <b>contraster</b> volontairement avec lui pour se faire remarquer. Les deux approches sont des choix de conception possibles, selon l’intention du projet.</p>`),
   HE('Concevoir le croquis d’un petit abri de jardin intégré à son environnement.','Dessiner le croquis d’un petit abri de jardin en réfléchissant à des matériaux et des couleurs qui s’intégreraient bien dans un environnement naturel donné.','20 minutes.','Papier, crayon.','Aucun matériel dangereux.','Mon projet tient-il compte de son impact environnemental ? Ai-je réfléchi à son intégration dans le paysage ?')],
  [{q:'Conçois le croquis d’un abri de jardin utilisant des matériaux naturels.',s:['Matériaux : bois non traité, toit végétalisé.','Couleurs : teintes proches de celles du jardin environnant.','Intégration : l’abri se fond dans le paysage plutôt que de le dominer.']}],
  ['Je sais que l’architecture et le design peuvent intégrer des préoccupations environnementales.','Je sais ce que signifie « intégrer » un projet à son environnement.','Je comprends qu’un projet peut aussi choisir de contraster volontairement avec son environnement.','Je sais concevoir un petit projet en pensant à son impact environnemental.'],
  ['Concevoir un projet sans jamais réfléchir à son impact environnemental.','Confondre intégration harmonieuse et contraste volontaire.','Ignorer que les matériaux choisis ont un impact écologique variable.'],
  ['Impact environnemental : matériaux, énergie, paysage.','Intégration harmonieuse ou contraste volontaire.','Choix de conception selon l’intention du projet.']),
 g:mix([bank([
  ['Penser l’impact environnemental d’un projet architectural implique de réfléchir…','aux matériaux utilisés et à l’énergie nécessaire',['uniquement à la couleur de la façade','uniquement au prix de vente','uniquement à la taille du bâtiment'],'Ces éléments ont une influence écologique directe.'],
  ['Un projet qui « s’intègre » à son environnement cherche à…','se fondre harmonieusement dans le paysage existant',['toujours contraster violemment avec le paysage','ignorer totalement son environnement','être invisible et sans aucune forme'],'Les couleurs et matériaux choisis rappellent souvent le contexte local.'],
  ['Un projet qui choisit volontairement de contraster avec son environnement cherche généralement à…','se faire remarquer ou affirmer une identité différente',['toujours mieux s’intégrer qu’un projet harmonieux','être systématiquement un échec de conception','copier exactement le paysage existant'],'C’est un choix de conception possible, selon l’intention.'],
  ['Les matériaux renouvelables (comme le bois) sont-ils parfois préférés pour limiter l’impact environnemental d’un projet ?','oui, c’est une tendance de plus en plus présente',['non, jamais préférés pour cette raison','non, les matériaux n’ont aucun lien avec l’environnement','non, cela ne concerne que les objets de petite taille'],'Ils répondent souvent mieux à des préoccupations écologiques.',2],
  {tf:'Un projet d’architecture ou de design peut intégrer des préoccupations environnementales dans ses choix.',v:true,e:'C’est une tendance de plus en plus marquée dans la conception contemporaine.'},
  {tf:'Intégration harmonieuse et contraste volontaire sont exactement la même démarche de conception.',v:false,e:'Ce sont deux approches différentes et opposées.',d:2},
  ['Un toit végétalisé sur un bâtiment peut-il contribuer à limiter son impact environnemental ?','oui, il peut améliorer l’isolation et favoriser la biodiversité',['non, un toit végétalisé n’a jamais aucun effet','non, cela aggrave toujours la pollution','non, cela ne concerne que les très petits bâtiments'],'C’est une pratique de plus en plus courante en architecture durable.'],
  ['Utiliser la lumière naturelle plutôt que l’éclairage artificiel dans la conception d’un bâtiment peut-il réduire sa consommation d’énergie ?','oui, bien orienter les ouvertures limite le besoin d’éclairage artificiel',['non, l’orientation du bâtiment n’a jamais aucun effet sur l’énergie','non, la lumière naturelle consomme toujours plus d’énergie','non, cela ne concerne que les très grands bâtiments'],'L’orientation et la taille des fenêtres influencent la consommation énergétique.',2],
  ['Un projet architectural peut-il prévoir de récupérer l’eau de pluie pour limiter sa consommation d’eau ?','oui, c’est une pratique de plus en plus intégrée aux projets durables',['non, cela n’a jamais aucun lien avec l’architecture','non, l’eau de pluie n’est jamais récupérable','non, cela ne concerne que l’agriculture'],'La gestion de l’eau fait partie des enjeux environnementaux pris en compte.'],
  ['Prévoir des arbres ou des espaces verts autour d’un bâtiment peut-il contribuer à son intégration paysagère ?','oui, la végétation aide souvent à relier le bâtiment à son environnement',['non, les espaces verts n’ont jamais aucun lien avec l’intégration','non, cela isole toujours davantage le bâtiment de son environnement','non, cela ne concerne que les parcs publics'],'La végétation participe à l’harmonie entre le bâti et le paysage.'],
  ['Deux bâtiments voisins conçus par des architectes différents peuvent-ils adopter des stratégies opposées (intégration et contraste) sur un même site ?','oui, chaque projet peut suivre une intention de conception différente',['non, tous les bâtiments d’un même site adoptent toujours la même stratégie','non, cela est toujours interdit par la loi','non, un seul choix de conception est jamais possible dans un quartier'],'Les choix de conception restent propres à chaque projet et architecte.',3],
  ['L’isolation thermique d’un bâtiment peut-elle réduire la quantité d’énergie nécessaire pour le chauffer ?','oui, une bonne isolation limite les pertes de chaleur',['non, l’isolation n’a jamais aucun effet sur l’énergie consommée','non, un bâtiment bien isolé consomme toujours davantage d’énergie','non, cela ne concerne que les très grands bâtiments industriels'],'C’est l’un des leviers principaux d’une architecture économe en énergie.']]),2])},

{id:'arts4f',name:'Construire un projet artistique personnel',icon:'📋',domain:'Projet',
 refs:[BO,EDU],
 tip:'Un bon projet artistique part d’une intention claire, explore plusieurs pistes avant de choisir, puis affine sa réalisation en tenant compte de contraintes (temps, matériaux).',
 c:C(`Construire un <b>projet artistique personnel</b> demande de combiner <b>intention</b>, <b>exploration</b> de plusieurs pistes, et <b>réalisation</b> en tenant compte de contraintes concrètes.`,
  [T('Partir d’une intention',`<p>Un projet personnel commence par une <b>intention</b> : une idée, une émotion, une question à explorer à travers la création. Cette intention guide ensuite les choix techniques, de matériaux et de composition faits pendant la réalisation.</p>`),
   T('Explorer avant de choisir, tenir compte des contraintes',`<p>Avant de se lancer dans la réalisation finale, on peut <b>explorer</b> plusieurs pistes (petits essais, croquis rapides) pour trouver la meilleure solution. On tient aussi compte de <b>contraintes</b> concrètes : le temps disponible, les matériaux accessibles, l’espace de travail.</p>`),
   HE('Construire un mini-projet personnel en 4 étapes : intention, exploration, réalisation, bilan.','Choisir une intention simple (représenter une saison, une émotion), explorer 2 ou 3 petites pistes rapides, réaliser la version choisie, puis noter un bilan personnel.','40 minutes.','Papier, crayons ou feutres, matériel selon le projet choisi.','Adapter la sécurité selon les matériaux utilisés.','Mon intention de départ est-elle claire ? Ai-je exploré plusieurs pistes avant de choisir ma réalisation finale ?')],
  [{q:'Construis un mini-projet sur l’intention « représenter le froid de l’hiver ».',s:['Exploration : essayer des couleurs froides (bleus), des formes pointues (glace), une composition vide.','Choix : retenir la piste qui exprime le mieux cette intention.','Réalisation et bilan : vérifier si le résultat final correspond bien à l’intention de départ.']}],
  ['Je sais formuler une intention claire pour un projet personnel.','Je sais explorer plusieurs pistes avant de choisir une direction.','Je sais tenir compte des contraintes concrètes (temps, matériaux, espace).','Je sais faire un bilan de mon projet par rapport à mon intention de départ.'],
  ['Se lancer dans la réalisation finale sans aucune exploration préalable.','Ignorer les contraintes concrètes de temps ou de matériaux disponibles.','Ne jamais comparer le résultat final à l’intention de départ.'],
  ['Intention claire au départ.','Exploration de plusieurs pistes avant choix.','Contraintes concrètes et bilan final.']),
 g:mix([d=>order('Remets dans l’ordre les étapes de construction d’un projet artistique personnel :',['Formuler une intention','Explorer plusieurs pistes','Réaliser la version choisie','Faire un bilan par rapport à l’intention de départ'],{expl:'Intention → exploration → réalisation → bilan.'}),2],
  [bank([
   ['La première étape d’un projet artistique personnel est généralement…','formuler une intention claire',['réaliser directement la version finale, sans aucune réflexion préalable','faire le bilan avant même de commencer','ignorer totalement toute intention'],'L’intention guide ensuite tous les choix du projet.'],
   ['Explorer plusieurs pistes avant de choisir une direction permet…','de trouver la solution la plus adaptée à son intention',['de perdre du temps pour rien','de rendre le projet final moins cohérent','d’éviter toute réflexion personnelle'],'Les essais rapides aident à affiner son choix.'],
   ['Pourquoi tenir compte des contraintes de temps et de matériaux disponibles dans un projet ?','pour que le projet reste réalisable concrètement',['ce n’est jamais nécessaire','pour rendre le projet toujours impossible à réaliser','pour ignorer totalement l’intention de départ'],'Un projet trop ambitieux par rapport aux contraintes risque d’échouer.'],
   ['Faire un bilan de son projet par rapport à son intention de départ permet…','de vérifier si le résultat correspond à ce qui était recherché',['de recommencer systématiquement le projet entier','de remplacer totalement l’intention initiale','de ne rien apprendre sur sa propre démarche'],'Cette réflexion finale nourrit la démarche artistique.'],
   {tf:'Un projet artistique personnel part généralement d’une intention claire qui guide les choix suivants.',v:true,e:'C’est le point de départ habituel d’une démarche de création.'},
   {tf:'Explorer plusieurs pistes avant de choisir une direction finale est toujours une perte de temps inutile.',v:false,e:'Cela aide au contraire à affiner son choix et à mieux répondre à son intention.',d:2},
  ['Un projet artistique personnel peut-il évoluer et s’écarter légèrement de l’intention initiale au cours de sa réalisation ?','oui, la création garde souvent une part d’ajustement en cours de route',['non, l’intention initiale doit toujours rester identique sans aucun changement','non, un projet qui évolue est toujours un échec','non, cela n’arrive jamais dans une démarche artistique'],'Le processus de création laisse souvent place à des ajustements.'],
  ['Demander un avis extérieur sur son projet en cours de réalisation peut-il aider à l’améliorer ?','oui, un regard extérieur peut apporter un éclairage nouveau',['non, cela n’apporte jamais rien','non, il faut toujours travailler seul sans aucun avis extérieur','non, un avis extérieur rend toujours le projet pire'],'Le regard d’autrui peut enrichir la démarche de création.'],
  ['Garder une trace (notes, croquis) des différentes étapes d’un projet permet-il de mieux comprendre sa propre démarche ensuite ?','oui, cela aide à analyser les choix faits tout au long du projet',['non, cela n’a jamais aucune utilité','non, seul le résultat final compte, sans aucun intérêt pour les étapes','non, il faut toujours effacer toute trace des étapes intermédiaires'],'Documenter son processus enrichit la réflexion sur sa propre pratique.'],
  ['Un projet artistique personnel peut-il s’inspirer d’une œuvre étudiée en classe tout en restant original ?','oui, s’inspirer d’une référence n’empêche pas d’apporter sa propre touche personnelle',['non, toute inspiration extérieure est toujours interdite','non, s’inspirer d’une œuvre rend automatiquement le projet identique à l’original','non, cela n’a jamais aucun lien avec l’originalité'],'S’inspirer et copier sont deux démarches différentes.'],
  ['Si les contraintes de temps obligent à simplifier un projet initialement plus ambitieux, cela remet-il en cause la valeur de la démarche artistique ?','non, adapter un projet à ses contraintes réelles reste une démarche valable',['oui, un projet simplifié n’a toujours aucune valeur','oui, il faut toujours renoncer complètement plutôt que d’adapter le projet','oui, les contraintes de temps ne devraient jamais influencer un projet artistique'],'S’adapter aux contraintes fait partie intégrante d’une démarche de création réaliste.']]),2])}
]);

MQ.add('arts','3',[
{id:'arts3a',name:'Créer à partir d’une intention',icon:'💭',domain:'Projet',
 refs:[BO,EDU],
 tip:'Une intention abstraite (« le temps qui passe ») demande souvent d’être traduite en choix concrets (couleurs qui s’effacent, formes qui se répètent et évoluent) pour devenir une œuvre visible.',
 c:C(`En 3e, créer à partir d’une <b>intention</b> devient plus exigeant : il s’agit de traduire une idée parfois abstraite en <b>choix plastiques</b> concrets et cohérents.`,
  [T('Traduire une idée abstraite',`<p>Une intention comme « le temps qui passe » ou « la solitude » est <b>abstraite</b> : elle doit être <b>traduite</b> en choix concrets (couleurs, formes, matières, composition) qui, ensemble, suggèrent cette idée au spectateur sans forcément la nommer explicitement.</p>`),
   T('Cohérence des choix plastiques',`<p>Pour qu’une intention soit perceptible, les différents choix faits (couleur, forme, matière, composition) doivent être <b>cohérents</b> entre eux : utiliser des couleurs vives et joyeuses pour exprimer la solitude créerait une contradiction qui brouillerait le message, à moins que ce décalage soit lui-même une intention volontaire.</p>`),
   HE('Traduire une intention abstraite en choix plastiques cohérents.','Choisir une intention abstraite (le temps qui passe, l’enfermement, la liberté) et réaliser une composition qui la traduit par des choix cohérents de couleur, forme et matière.','40 minutes.','Matériaux au choix selon le projet (papier, peinture, matériaux de récupération).','Adapter la sécurité selon les matériaux utilisés.','Mes choix plastiques sont-ils cohérents avec mon intention ? Un spectateur pourrait-il percevoir mon intention sans que je l’explique ?')],
  [{q:'Traduis l’intention « l’enfermement » en choix plastiques.',s:['Formes : lignes fermées, grilles, cadres qui se répètent.','Couleurs : teintes sombres ou étouffées.','Composition : sujet resserré, peu d’espace libre autour de lui.']}],
  ['Je sais traduire une intention abstraite en choix plastiques concrets.','Je comprends l’importance de la cohérence entre les différents choix faits.','Je sais qu’un décalage volontaire entre intention et choix peut aussi être une démarche artistique.','Je sais vérifier si mon intention est perceptible sans l’expliquer.'],
  ['Choisir des éléments plastiques sans aucun lien avec l’intention de départ.','Créer une incohérence non volontaire entre les choix faits.','Ne jamais vérifier si l’intention reste perceptible pour un spectateur extérieur.'],
  ['Intention abstraite → choix plastiques concrets.','Cohérence entre couleur, forme, matière, composition.','Décalage volontaire = démarche artistique possible.']),
 g:mix([sort({'Choix cohérent avec l’intention « la solitude »':['une composition avec un seul petit élément dans un grand espace vide','des couleurs froides et ternes'],'Choix cohérent avec l’intention « la fête »':['des couleurs vives et nombreuses','une composition dense, remplie d’éléments variés']},{q:'« %s » correspond plutôt à l’intention…'}),2],
  [bank([
   ['Traduire une intention abstraite en choix plastiques signifie…','transformer une idée en couleurs, formes et matières concrètes',['ignorer totalement l’intention de départ','écrire uniquement un texte explicatif sans aucune réalisation','copier exactement une œuvre existante'],'Cette traduction rend l’intention perceptible visuellement.'],
   ['Pourquoi la cohérence entre les différents choix plastiques est-elle importante ?','elle rend l’intention plus clairement perceptible par le spectateur',['elle n’a jamais aucune importance','elle complique toujours inutilement la création','elle empêche toute créativité'],'Des choix contradictoires peuvent brouiller le message.'],
   ['Un décalage volontaire entre l’intention et les choix plastiques peut-il être une démarche artistique en soi ?','oui, ce contraste peut créer un effet recherché',['non, jamais','non, cela constitue toujours une erreur','non, un décalage ne peut jamais être volontaire'],'L’ironie ou le contraste peuvent être des choix assumés.',2],
   ['Pour vérifier qu’une intention est perceptible, on peut…','demander à un spectateur ce qu’il ressent face à l’œuvre, sans lui expliquer l’intention au préalable',['expliquer systématiquement l’intention avant de montrer l’œuvre','ne jamais montrer l’œuvre à personne','ignorer totalement le ressenti du spectateur'],'Le ressenti spontané révèle si l’intention passe bien.'],
   {tf:'Les différents choix plastiques d’une œuvre (couleur, forme, matière) doivent généralement être cohérents avec l’intention recherchée.',v:true,e:'Cette cohérence renforce la perception de l’intention.'},
   {tf:'Une intention abstraite comme « le temps qui passe » ne peut jamais être traduite par des choix plastiques concrets.',v:false,e:'C’est justement l’objectif de la démarche de création : traduire l’abstrait en concret.',d:2},
  ['Pour traduire l’intention « la croissance » dans une composition, on pourrait choisir…','des formes qui s’élargissent progressivement, du bas vers le haut',['uniquement des formes identiques répétées sans aucune évolution','uniquement des couleurs uniformes sans aucune variation','uniquement des traits brisés sans lien entre eux'],'Une progression visuelle peut traduire l’idée de croissance.'],
  ['Une intention très vague, sans aucune précision, est-elle plus facile ou plus difficile à traduire en choix plastiques cohérents ?','plus difficile, car il manque des repères précis pour orienter les choix',['plus facile, car tout devient automatiquement possible','sans aucune différence avec une intention précise','impossible à traduire dans tous les cas'],'Préciser son intention aide généralement à faire des choix cohérents.',2]]),2])},

{id:'arts3b',name:'Art, réalité et fiction',icon:'🎭',domain:'Représentation',
 refs:[BO,EDU],
 tip:'Une œuvre peut emprunter des éléments à la réalité (un lieu, un événement réel) tout en les combinant avec des éléments fictifs : la frontière entre réalité et fiction n’est pas toujours nette dans l’art.',
 c:C(`Une œuvre d’art peut s’appuyer sur la <b>réalité</b> ou inventer une <b>fiction</b>, et souvent combiner les deux, brouillant volontairement la frontière entre ce qui est vrai et ce qui est inventé.`,
  [T('Puiser dans le réel',`<p>Certaines œuvres s’appuient directement sur des éléments <b>réels</b> : un lieu existant, un événement historique, un objet du quotidien. Le <b>réalisme</b> (étudié en histoire des arts) cherche à représenter fidèlement cette réalité, sans l’idéaliser.</p>`),
   T('Inventer une fiction',`<p>D’autres œuvres créent une <b>fiction</b> : des personnages, des lieux ou des événements imaginaires. La fiction permet d’explorer des idées ou des émotions sans être limitée par le réel, mais elle peut rester <b>crédible</b> en gardant une cohérence interne, ou revendiquer son caractère totalement fantastique.</p>`),
   HE('Créer une œuvre mêlant un élément réel et un élément fictif.','Choisir un objet ou un lieu réel observé, et l’intégrer dans une composition où il côtoie un élément clairement imaginaire.','30 minutes.','Papier, crayons ou feutres.','Aucun matériel dangereux.','Mon œuvre combine-t-elle clairement un élément réel et un élément fictif ? Cette combinaison crée-t-elle un effet intéressant ?')],
  [{q:'Analyse une œuvre représentant une vraie place de ville avec une créature imaginaire géante qui s’y promène.',s:['La place représentée est un élément réel, reconnaissable.','La créature imaginaire est un élément fictif.','Le mélange des deux crée un effet de surprise ou d’étrangeté.']}],
  ['Je sais distinguer un élément réel et un élément fictif dans une œuvre.','Je comprends qu’une œuvre peut combiner réalité et fiction.','Je sais ce que recherche une démarche réaliste.','Je comprends qu’une fiction peut rester cohérente sans être réaliste.'],
  ['Croire qu’une œuvre doit toujours être soit totalement réelle, soit totalement fictive.','Confondre réalisme et fiction totale.','Ignorer qu’une fiction peut garder une cohérence interne malgré son caractère imaginaire.'],
  ['Réalité : s’appuie sur le réel (réalisme).','Fiction : invente personnages, lieux, événements.','Mélange réalité/fiction possible et fréquent.']),
 g:mix([sort({'Élément réel':['un monument existant dans une ville connue','un objet du quotidien reconnaissable'],'Élément fictif':['une créature qui n’existe pas dans la réalité','un lieu totalement imaginaire']},{q:'« %s » relève d’un…'}),2],
  [bank([
   ['Une œuvre réaliste cherche à…','représenter fidèlement la réalité, sans l’idéaliser',['inventer uniquement des éléments fantastiques','ignorer totalement le monde réel','déformer systématiquement toute observation'],'C’est l’un des principes du mouvement réaliste étudié en histoire des arts.'],
   ['Une fiction artistique peut-elle rester cohérente, même si elle est totalement imaginaire ?','oui, une cohérence interne peut rendre une fiction crédible',['non, une fiction est toujours incohérente par définition','non, la cohérence n’a jamais aucun lien avec la fiction','non, seule la réalité peut être cohérente'],'La cohérence des règles internes rend un monde imaginaire convaincant.'],
   ['Une œuvre peut-elle combiner un élément réel et un élément fictif dans la même composition ?','oui, cette combinaison est fréquente en art',['non, jamais','non, cela rendrait toujours l’œuvre incompréhensible','non, les deux catégories s’excluent toujours totalement'],'De nombreuses œuvres jouent sur ce mélange.'],
   ['Pourquoi certains artistes choisissent-ils de brouiller la frontière entre réalité et fiction ?','pour créer un effet de surprise, de questionnement ou d’étrangeté',['par manque de talent','sans aucune intention particulière','parce que c’est toujours obligatoire'],'Ce procédé interroge la perception du spectateur.',2],
   {tf:'Une œuvre peut s’appuyer sur un lieu réel tout en y intégrant des éléments imaginaires.',v:true,e:'Ce mélange est une démarche artistique fréquente.'},
   {tf:'Le réalisme en art cherche à inventer des mondes totalement fantastiques, sans aucun lien avec la réalité observable.',v:false,e:'Il cherche au contraire à représenter fidèlement la réalité.',d:2},
  ['Une fiction artistique peut-elle aborder des questions réelles (peur, espoir, injustice) à travers des éléments imaginaires ?','oui, la fiction permet souvent d’explorer des questions réelles autrement',['non, la fiction ne traite jamais de questions réelles','non, cela ne concerne que les œuvres totalement réalistes','non, les éléments imaginaires empêchent toujours toute réflexion sérieuse'],'La fiction est un détour possible vers des questions bien réelles.'],
  ['Présenter un lieu réel transformé par des éléments impossibles (objets qui flottent, couleurs irréelles) relève…','d’un mélange entre réalité et fiction',['uniquement d’une erreur technique de représentation','uniquement d’une œuvre purement réaliste','d’une impossibilité artistique totale'],'C’est une démarche fréquente pour créer un effet d’étrangeté ou de rêve.']]),2])},

{id:'arts3c',name:'Image numérique, montage et diffusion',icon:'💻',domain:'Image',
 refs:[BO,EDU],
 tip:'Une image numérique peut être modifiée facilement (recadrage, filtres, retouches) : cette facilité pose des questions sur la fiabilité de ce qu’on voit en ligne.',
 c:C(`L’<b>image numérique</b> se crée, se modifie et se <b>diffuse</b> différemment d’une image traditionnelle : ces spécificités transforment les pratiques artistiques contemporaines.`,
  [T('Créer et modifier une image numérique',`<p>Une image numérique est composée de <b>pixels</b> et peut être modifiée facilement : recadrage, changement de couleurs, ajout ou suppression d’éléments, application de <b>filtres</b>. Cette facilité de modification distingue fortement l’image numérique d’une peinture traditionnelle, plus difficile à corriger.</p>`),
   T('La diffusion en ligne',`<p>Une image numérique peut être <b>diffusée</b> instantanément à un très large public via les réseaux. Cette diffusion rapide pose des questions sur le respect du <b>droit d’auteur</b> (voir les chapitres d’EMI) et sur la <b>fiabilité</b> des images vues en ligne, qui peuvent avoir été modifiées sans que cela soit visible.</p>`),
   HE('Modifier numériquement ou par collage une image pour en changer le sens.','Si un outil numérique est disponible (avec l’accord d’un adulte), modifier une photo (filtre, recadrage) ; sinon, réaliser un collage papier qui transforme le sens d’une image de départ.','30 minutes.','Un outil numérique (facultatif) ou papier, ciseaux, colle, images à découper.','Demander l’accord d’un adulte pour l’usage d’outils numériques ; prudence avec les ciseaux.','Ma modification a-t-elle clairement changé le sens de l’image de départ ? Ai-je respecté les droits sur les images utilisées ?')],
  [{q:'Explique comment un filtre numérique peut changer la perception d’une photo.',s:['Un filtre peut changer les couleurs, l’ambiance générale de l’image.','Une photo avec un filtre « sépia » paraîtra plus ancienne ou nostalgique.','Le choix du filtre reflète une intention esthétique du créateur de l’image.']}],
  ['Je sais qu’une image numérique est composée de pixels, facilement modifiable.','Je comprends l’effet d’un filtre sur la perception d’une image.','Je comprends les enjeux de la diffusion rapide d’une image en ligne.','Je sais qu’une image modifiée peut poser des questions de fiabilité.'],
  ['Croire qu’une image numérique ne peut jamais être modifiée.','Ignorer que la diffusion en ligne pose des questions de droit d’auteur.','Penser qu’une image vue en ligne est toujours fidèle à la réalité sans aucune modification possible.'],
  ['Image numérique : pixels, modification facile (filtres, recadrage).','Diffusion rapide en ligne.','Questions de droit d’auteur et de fiabilité.']),
 g:mix([bank([
  ['Une image numérique est composée de…','pixels',['uniquement de peinture','uniquement de papier','uniquement de pierre'],'Chaque petit point coloré forme l’image complète.'],
  ['Un filtre appliqué à une photo peut…','changer son ambiance ou ses couleurs',['uniquement agrandir la photo sans rien changer d’autre','supprimer totalement l’image','rien de particulier'],'Il modifie la perception générale de l’image.'],
  ['Pourquoi la diffusion rapide d’images en ligne pose-t-elle des questions de droit d’auteur ?','car une image peut être copiée et republiée sans l’accord de son auteur',['cela n’a jamais aucun lien avec le droit d’auteur','car les images en ligne n’appartiennent jamais à personne','car cela concerne uniquement la musique'],'La facilité de copie complique le respect des droits.',2],
  ['Une image publiée en ligne peut-elle avoir été modifiée sans que cela soit visible à l’œil nu ?','oui, certaines retouches sont très difficiles à repérer',['non, toute modification est toujours visible immédiatement','non, les images en ligne ne sont jamais modifiées','non, cela ne concerne que les vidéos'],'C’est pourquoi la vérification des images reste importante (voir les chapitres d’EMI).',2],
  {tf:'Une image numérique peut être modifiée beaucoup plus facilement qu’une peinture traditionnelle.',v:true,e:'La manipulation numérique (recadrage, filtres) est rapide et réversible.'},
  {tf:'La diffusion d’une image numérique en ligne est toujours instantanée et sans aucune conséquence.',v:false,e:'Elle peut avoir des conséquences, notamment sur le respect du droit d’auteur et de la vie privée.',d:2},
  ['Un collage numérique, combinant plusieurs photos différentes en une seule image, relève-t-il d’une technique de montage ?','oui, le montage d’images combine plusieurs sources en une seule composition',['non, un collage ne concerne jamais le numérique','non, cela n’a aucun lien avec le montage','non, seule la vidéo permet un montage'],'Le photomontage est une technique de création d’images numériques.',2],
  ['Créditer l’auteur d’une image réutilisée dans un montage numérique relève…','d’une pratique respectueuse du droit d’auteur',['d’une pratique inutile sans aucune importance','d’une obligation réservée uniquement aux professionnels','d’une pratique qui n’existe jamais en arts plastiques'],'C’est une marque de respect envers le travail d’autrui.'],
  ['Une image numérique modifiée peut-elle être partagée aussi largement qu’une image non modifiée ?','oui, la diffusion ne dépend pas du fait que l’image ait été modifiée ou non',['non, seules les images non modifiées peuvent être partagées','non, une image modifiée est toujours automatiquement bloquée','non, cela ne concerne que les photographies professionnelles'],'La diffusion en ligne ne distingue pas automatiquement image modifiée et image d’origine.'],
  ['Superposer plusieurs calques (couches d’image) en infographie permet-il de combiner différents éléments visuels progressivement ?','oui, chaque calque peut contenir un élément distinct assemblé ensuite',['non, un seul calque unique est toujours utilisé','non, les calques n’existent que pour la vidéo','non, cela concerne uniquement la peinture traditionnelle'],'Le travail en calques est une méthode courante en création numérique.',2],
  ['Une image numérique peut-elle être agrandie fortement sans perte de qualité, quelle que soit sa résolution d’origine ?','non, une faible résolution d’origine entraîne souvent une perte de netteté en cas d’agrandissement important',['oui, toujours parfaitement nette quelle que soit la résolution','oui, car le numérique ne connaît jamais de limite de qualité','oui, uniquement pour les images en noir et blanc'],'La résolution d’origine limite la qualité d’un agrandissement.',2],
  ['Associer une image fixe retouchée à un texte ou une légende peut-il en changer complètement l’interprétation ?','oui, la légende ou le texte associé influence fortement la lecture de l’image',['non, le texte n’a jamais aucune influence sur la perception d’une image','non, seule l’image compte, jamais le texte qui l’accompagne','non, cela ne concerne que les œuvres sans aucun texte'],'Texte et image interagissent souvent pour construire un sens.']]),2])},

{id:'arts3d',name:'Installation, espace et spectateur',icon:'🏛️',domain:'Espace',
 refs:[BO,EDU],
 tip:'Une installation transforme l’expérience du spectateur en l’invitant à se déplacer physiquement dans l’œuvre, plutôt qu’à l’observer de loin comme devant une peinture.',
 c:C(`L’<b>installation</b> est une forme artistique qui occupe un <b>espace</b> entier, dans laquelle le <b>spectateur</b> peut se déplacer et devenir partie intégrante de l’expérience.`,
  [T('Occuper un espace',`<p>Une installation peut occuper une <b>pièce entière</b>, voire un espace extérieur, en combinant plusieurs éléments (objets, lumières, sons) dans une organisation pensée globalement. Contrairement à une peinture accrochée au mur, l’installation transforme l’<b>espace réel</b> dans lequel elle se trouve.</p>`),
   T('Le rôle du spectateur',`<p>Dans une installation, le <b>spectateur</b> n’est plus seulement face à l’œuvre : il peut <b>entrer</b> dans l’œuvre, s’y déplacer, parfois la <b>toucher</b> ou interagir avec elle. Son parcours personnel dans l’espace influence son expérience : deux spectateurs peuvent vivre l’installation différemment selon leur trajet et leur attention.</p>`),
   HE('Imaginer le plan d’une petite installation occupant un coin de salle.','Dessiner le plan vu du dessus d’une installation simple occupant un coin de pièce, en indiquant la position des éléments et le parcours possible du spectateur.','30 minutes.','Papier, crayon.','Aucun matériel dangereux.','Mon plan montre-t-il clairement l’organisation de l’espace ? Ai-je pensé au parcours possible du spectateur dans cet espace ?')],
  [{q:'Imagine une installation sur le thème « la mémoire », occupant un coin de salle.',s:['Organisation : plusieurs objets personnels suspendus à différentes hauteurs.','Parcours : le spectateur doit se pencher et se déplacer pour observer chaque objet.','Cette expérience physique renforce l’intention de fouiller dans des souvenirs.']}],
  ['Je sais ce qu’est une installation en arts plastiques.','Je comprends la différence entre observer une peinture et se déplacer dans une installation.','Je comprends que le spectateur devient actif dans une installation.','Je sais imaginer l’organisation spatiale d’une installation simple.'],
  ['Confondre une installation avec une simple peinture accrochée au mur.','Ignorer le rôle actif du spectateur dans une installation.','Penser que tous les spectateurs vivent nécessairement la même expérience face à une installation.'],
  ['Installation : occupe un espace entier.','Spectateur actif : se déplace, parfois interagit.','Parcours personnel = expérience variable selon le spectateur.']),
 g:mix([bank([
  ['Une installation, contrairement à une peinture, occupe généralement…','un espace entier dans lequel le spectateur peut se déplacer',['uniquement une surface plane accrochée au mur','uniquement un petit cadre','aucun espace particulier'],'C’est l’une des différences majeures avec une œuvre plane.'],
  ['Dans une installation, le spectateur peut-il devenir actif, en se déplaçant ou en interagissant avec l’œuvre ?','oui, c’est souvent l’une des spécificités de cette forme artistique',['non, il reste toujours totalement immobile','non, il observe toujours uniquement de loin, comme devant une peinture','non, cela n’existe dans aucune installation'],'Le déplacement du spectateur fait souvent partie de l’expérience proposée.'],
  ['Deux spectateurs peuvent-ils vivre différemment une même installation ?','oui, selon leur parcours et leur attention personnelle',['non, l’expérience est toujours rigoureusement identique pour tous','non, une installation ne propose jamais plusieurs parcours possibles','non, cela ne concerne que la peinture'],'Le trajet dans l’espace influence l’expérience vécue.'],
  ['Une installation peut-elle combiner plusieurs types d’éléments (objets, lumières, sons) ?','oui, elle combine souvent plusieurs médiums à la fois',['non, elle n’utilise jamais qu’un seul type d’élément','non, le son n’a jamais sa place dans une installation','non, la lumière ne peut jamais faire partie d’une installation'],'Cette combinaison enrichit l’expérience sensorielle proposée.',2],
  {tf:'Une installation transforme l’espace réel dans lequel elle se trouve.',v:true,e:'Elle occupe et organise cet espace de façon pensée.'},
  {tf:'Le spectateur d’une installation reste toujours totalement passif, comme devant une peinture classique.',v:false,e:'Il peut au contraire devenir actif, se déplacer, voire interagir.',d:2},
  ['L’éclairage d’une pièce peut-il faire partie des choix pensés dans une installation ?','oui, la lumière peut orienter le regard et créer une ambiance particulière',['non, l’éclairage n’a jamais aucun lien avec une installation','non, seule la lumière naturelle peut être utilisée','non, la lumière reste toujours neutre dans une installation'],'La lumière est un élément à part entière de la composition spatiale.'],
  ['Une installation conçue pour une grande salle peut-elle fonctionner exactement de la même façon dans un tout petit espace ?','pas nécessairement, la taille de l’espace influence souvent l’expérience proposée',['oui, toujours exactement de la même façon','oui, l’espace n’a jamais aucune influence sur une installation','oui, car l’installation ne dépend jamais de son lieu d’exposition'],'La relation entre l’œuvre et son espace fait partie de la conception.',2],
  ['Une installation en extérieur doit-elle tenir compte de contraintes différentes d’une installation en intérieur (météo, lumière du jour) ?','oui, l’environnement extérieur impose des contraintes spécifiques',['non, les contraintes sont toujours rigoureusement identiques','non, la météo n’a jamais aucune influence sur une œuvre extérieure','non, cela ne concerne que les installations en intérieur'],'L’environnement extérieur ajoute des paramètres à prendre en compte.'],
  ['Le son ambiant d’une installation peut-il modifier la perception des objets et de l’espace qui l’entourent ?','oui, le son contribue à l’atmosphère générale perçue par le spectateur',['non, le son n’a jamais aucun lien avec la perception de l’espace','non, seule la vue compte dans une installation','non, le son reste toujours totalement indépendant de l’espace'],'L’environnement sonore participe à l’expérience globale.',2],
  ['Une installation peut-elle être conçue pour n’être visible que d’un point de vue précis, un peu comme un trompe-l’œil ?','oui, certains projets jouent sur un point de vue privilégié pour révéler l’œuvre complète',['non, une installation se perçoit toujours identiquement depuis tous les points de vue','non, le point de vue n’a jamais aucune importance dans une installation','non, cela concerne uniquement la peinture'],'Le choix du point de vue peut faire partie intégrante de la conception.',3],
  ['La durée pendant laquelle un spectateur reste dans une installation peut-elle varier selon les personnes ?','oui, chacun peut choisir de rester plus ou moins longtemps selon son intérêt',['non, chaque spectateur reste toujours exactement le même temps','non, la durée de visite est toujours imposée strictement','non, cela ne concerne que les œuvres filmées'],'La liberté de parcours inclut souvent la liberté de durée.']]),2])},

{id:'arts3e',name:'Art, société et engagement',icon:'✊',domain:'Culture artistique',
 refs:[BO,EDU],
 tip:'Une œuvre engagée prend position sur une question sociale ou politique, souvent pour sensibiliser ou faire réagir le public, plutôt que pour décorer simplement un espace.',
 c:C(`L’art peut être un moyen d’<b>engagement</b> sur des questions de <b>société</b> : certains artistes utilisent leur création pour sensibiliser, dénoncer ou faire réfléchir sur des enjeux sociaux, politiques ou environnementaux.`,
  [T('L’art engagé',`<p>Une œuvre <b>engagée</b> prend position sur une question de société (injustice, guerre, environnement, droits humains). Elle cherche souvent à <b>sensibiliser</b> le public ou à provoquer une <b>réflexion</b>, voire une action. « Guernica » de Picasso (étudiée en histoire des arts) est un exemple célèbre d’œuvre engagée contre la violence de la guerre.</p>`),
   T('Différentes formes d’engagement artistique',`<p>L’engagement peut passer par le <b>street art</b> (messages visibles dans l’espace public), des <b>installations</b> qui interpellent le public, des <b>performances</b> qui mettent en scène une problématique, ou des œuvres plus traditionnelles qui abordent des sujets de société par leur sujet ou leur contexte de création.</p>`),
   HE('Créer une petite affiche engagée sur un sujet de société qui te tient à cœur.','Choisir un sujet de société (environnement, égalité, harcèlement) et créer une affiche simple combinant image et message court pour sensibiliser.','30 minutes.','Papier, feutres ou crayons de couleur.','Aucun matériel dangereux.','Mon message est-il clair et visible ? Mon image renforce-t-elle efficacement ce message ?')],
  [{q:'Analyse « Guernica » de Picasso comme œuvre engagée.',s:['Sujet : dénonciation du bombardement d’une ville pendant la guerre civile espagnole.','Forme : déformations qui expriment l’horreur et la souffrance.','Engagement : l’œuvre prend clairement position contre la violence de la guerre.']}],
  ['Je sais ce qu’est une œuvre artistique engagée.','Je connais un exemple d’œuvre engagée (Guernica).','Je connais différentes formes d’engagement artistique (street art, installation, performance).','Je sais créer une petite production qui prend position sur un sujet de société.'],
  ['Croire qu’une œuvre d’art ne peut jamais prendre position sur un sujet de société.','Confondre une œuvre purement décorative et une œuvre engagée.','Ignorer les différentes formes possibles d’engagement artistique.'],
  ['Art engagé : prend position sur un sujet de société.','Exemple : Guernica (Picasso) contre la guerre.','Formes variées : street art, installation, performance.']),
 g:mix([bank([
  ['Une œuvre d’art engagée cherche notamment à…','sensibiliser le public sur une question de société',['uniquement décorer un espace sans aucun message','ignorer totalement les enjeux sociaux','éviter systématiquement toute prise de position'],'L’engagement implique une intention de faire réfléchir ou réagir.'],
  ['« Guernica » de Picasso est un exemple d’œuvre engagée contre…','la violence de la guerre',['la pollution industrielle uniquement','les inégalités économiques uniquement','la mode de son époque'],'Elle réagit au bombardement d’une ville pendant la guerre civile espagnole.'],
  ['Le street art peut-il être une forme d’engagement artistique dans l’espace public ?','oui, de nombreuses œuvres de street art portent des messages sociaux ou politiques',['non, le street art ne porte jamais aucun message','non, cela concerne uniquement la décoration','non, l’engagement artistique n’existe que dans les musées'],'L’espace public touche un large public de passants.'],
  ['Une performance artistique peut-elle mettre en scène une problématique sociale pour sensibiliser le public ?','oui, c’est une des formes possibles d’engagement artistique',['non, jamais','non, une performance ne peut traiter que de sujets légers','non, cela n’a aucun lien avec l’engagement'],'Le corps en action peut porter un message fort.',2],
  {tf:'Une œuvre artistique peut prendre position sur une question de société comme la guerre ou l’environnement.',v:true,e:'C’est le principe même de l’art engagé.'},
  {tf:'L’engagement artistique ne peut s’exprimer que par la peinture traditionnelle, jamais par d’autres formes comme le street art ou la performance.',v:false,e:'L’engagement peut prendre de nombreuses formes différentes.',d:2},
  ['Une œuvre engagée sur l’environnement pourrait-elle utiliser des matériaux recyclés pour renforcer son message ?','oui, le choix des matériaux peut lui-même porter une partie du message',['non, le matériau n’a jamais aucun lien avec le message','non, une œuvre engagée ne peut jamais utiliser de matériaux recyclés','non, cela concerne uniquement la peinture traditionnelle'],'La matière utilisée peut renforcer la cohérence du message engagé.'],
  ['Une œuvre engagée cherche-t-elle parfois à provoquer une réaction forte, pas seulement à informer calmement ?','oui, certaines œuvres engagées jouent sur le choc ou la surprise pour marquer le public',['non, une œuvre engagée reste toujours parfaitement neutre et calme','non, provoquer une réaction est toujours interdit en art','non, cela concerne uniquement les œuvres humoristiques'],'Le choc visuel peut renforcer l’impact du message engagé.',2],
  ['Une œuvre engagée datant d’une époque passée peut-elle encore résonner avec des questions d’aujourd’hui ?','oui, certains messages (contre la guerre, pour l’égalité) restent actuels au-delà de leur époque',['non, une œuvre engagée ne concerne toujours que son époque précise de création','non, le message d’une œuvre ancienne disparaît toujours avec le temps','non, cela ne concerne que les œuvres très récentes'],'Certains messages engagés gardent une portée universelle dans le temps.',2],
  ['Une œuvre engagée doit-elle forcément être comprise de la même façon par tous les spectateurs ?','pas nécessairement, chacun peut l’interpréter selon sa propre sensibilité, tout en percevant un message général',['oui, une seule lecture possible existe toujours, sans aucune nuance','oui, sinon l’œuvre est considérée comme un échec total','oui, l’engagement interdit toujours toute interprétation personnelle'],'Une œuvre engagée peut laisser place à des nuances de lecture tout en portant un message.',3],
  ['Une œuvre engagée peut-elle être réalisée collectivement, par plusieurs personnes partageant la même cause ?','oui, de nombreuses œuvres engagées résultent d’un travail collectif',['non, une œuvre engagée est toujours réalisée par une seule personne','non, le travail collectif n’existe jamais dans une démarche engagée','non, cela ne concerne que les œuvres individuelles'],'L’engagement collectif renforce parfois la portée du message porté.'],
  ['Une œuvre engagée installée dans un lieu public précis (devant un bâtiment symbolique, par exemple) peut-elle renforcer son message grâce à ce lieu ?','oui, le choix du lieu peut donner un sens supplémentaire au message porté',['non, le lieu n’a jamais aucun lien avec le message d’une œuvre','non, une œuvre engagée ne peut jamais être installée dans l’espace public','non, cela ne concerne que les œuvres exposées en musée'],'Le contexte spatial peut renforcer la portée symbolique d’une œuvre.',3]]),2])},

{id:'arts3f',name:'Présenter un projet et construire une analyse critique',icon:'🎤',domain:'Oral artistique',
 refs:[BO,EDU],
 tip:'Une analyse critique rigoureuse distingue ce qui est observé objectivement (les choix faits) de ce qui est une appréciation personnelle, tout en justifiant chaque jugement par des éléments précis.',
 c:C(`En fin de collège, présenter un projet personnel demande de construire une véritable <b>analyse critique</b> : observer, interpréter, et évaluer sa propre démarche avec rigueur.`,
  [T('Construire une analyse critique',`<p>Une analyse critique distingue l’<b>observation</b> objective (les choix techniques faits) de l’<b>appréciation</b> personnelle (ce qui a bien ou moins bien fonctionné selon son propre jugement). Chaque appréciation doit être <b>justifiée</b> par un élément précis, plutôt que d’être une simple impression.</p>`),
   T('Présenter avec rigueur et authenticité',`<p>Présenter son projet demande d’expliquer son <b>intention</b> de départ, les <b>choix</b> faits pendant la réalisation, et une évaluation <b>honnête</b> du résultat final par rapport à cette intention. Reconnaître les limites ou difficultés rencontrées fait partie d’une présentation sincère et réfléchie, et non d’un aveu de faiblesse.</p>`),
   HE('Préparer et présenter oralement un bilan critique d’un projet réalisé dans l’année.','Préparer une présentation de 2 minutes sur un projet personnel réalisé cette année : intention, choix faits, analyse critique du résultat.','20 minutes de préparation, 2 minutes de présentation.','Le projet concerné, éventuellement des notes.','Aucune sécurité particulière pour cette activité orale.','Mon analyse distingue-t-elle bien observation et appréciation personnelle ? Ai-je justifié mes jugements par des éléments précis ?')],
  [{q:'Présente un bilan critique d’un projet où l’intention n’a été que partiellement atteinte.',s:['Intention de départ : exprimer le mouvement par des formes dynamiques.','Observation : les formes restent plutôt statiques dans le résultat final.','Appréciation justifiée : l’intention n’est que partiellement atteinte, un travail supplémentaire sur la composition aurait pu renforcer l’effet recherché.']}],
  ['Je sais distinguer observation objective et appréciation personnelle.','Je sais justifier chaque appréciation par un élément précis.','Je sais présenter une évaluation honnête de mon propre travail.','Je comprends que reconnaître une limite n’est pas un aveu de faiblesse, mais une démarche réfléchie.'],
  ['Confondre observation objective et simple impression personnelle non justifiée.','Présenter uniquement les réussites sans jamais mentionner les difficultés rencontrées.','Donner une appréciation sans aucun élément précis pour la justifier.'],
  ['Observation (faits) vs appréciation (jugement justifié).','Intention, choix, évaluation honnête du résultat.','Reconnaître une limite = démarche réfléchie, pas une faiblesse.']),
 g:mix([bank([
  ['Une analyse critique distingue généralement…','l’observation objective des choix faits et l’appréciation personnelle justifiée',['uniquement un avis sans aucune observation','uniquement une description sans aucun jugement','rien de particulier, tout se mélange toujours'],'Cette distinction rend l’analyse plus rigoureuse.'],
  ['Chaque appréciation portée sur un projet doit-elle être justifiée par un élément précis ?','oui, sinon ce n’est qu’une impression non argumentée',['non, aucune justification n’est jamais nécessaire','non, une appréciation est toujours évidente sans preuve','non, seule l’intuition compte dans une analyse critique'],'La justification rend le jugement plus crédible et rigoureux.'],
  ['Reconnaître que son intention n’a été que partiellement atteinte lors d’une présentation est-ce un signe de faiblesse ?','non, c’est une démarche réfléchie et honnête',['oui, toujours un signe de faiblesse à éviter absolument','oui, il faut toujours prétendre une réussite totale','oui, cela discrédite systématiquement la présentation'],'La lucidité sur son propre travail est une qualité, pas un défaut.'],
  ['Présenter son intention de départ avant d’évaluer le résultat final permet…','de mesurer concrètement l’écart entre le projet et sa réalisation',['de remplacer totalement l’évaluation du résultat','de rendre l’évaluation impossible','de cacher les choix réellement faits'],'Cette comparaison structure une analyse critique rigoureuse.',2],
  {tf:'Une bonne analyse critique justifie chaque appréciation par un élément précis observé dans le travail réalisé.',v:true,e:'Cela distingue une analyse rigoureuse d’une simple opinion.'},
  {tf:'Une présentation de projet ne doit jamais mentionner les difficultés rencontrées pendant la réalisation.',v:false,e:'Mentionner les difficultés, avec honnêteté, fait partie d’une présentation réfléchie.',d:2},
  ['Comparer son projet final à ses premières explorations peut-il enrichir une analyse critique ?','oui, cela montre l’évolution de la démarche depuis le début du projet',['non, cela n’a jamais aucun intérêt','non, les premières explorations doivent toujours être oubliées','non, seul le résultat final compte, sans aucun lien avec le processus'],'Montrer l’évolution de la réflexion enrichit la présentation.'],
  ['Proposer, lors de la présentation, une piste d’amélioration pour une future réalisation est-ce une démarche pertinente ?','oui, cela montre une capacité à se projeter et à progresser',['non, cela n’a jamais aucune utilité','non, il faut toujours considérer son projet comme totalement terminé et parfait','non, proposer une amélioration est toujours un aveu d’échec'],'Se projeter vers une amélioration future est une démarche constructive.'],
  ['Adapter le niveau de détail de sa présentation selon le temps imparti relève-t-il d’une bonne préparation ?','oui, choisir les informations essentielles à présenter dans le temps donné est une compétence utile',['non, il faut toujours tout dire sans aucune sélection, quelle que soit la durée prévue','non, le temps imparti n’a jamais aucune importance','non, mieux vaut toujours dépasser largement le temps prévu'],'Sélectionner l’essentiel aide à respecter les contraintes de temps.'],
  ['Relier son analyse critique à des notions vues en classe (intention, cohérence des choix) peut-il renforcer la présentation ?','oui, cela montre une bonne maîtrise du vocabulaire et des notions étudiées',['non, cela n’apporte jamais rien à la présentation','non, il faut toujours éviter tout vocabulaire technique','non, les notions étudiées n’ont jamais aucun lien avec son propre projet'],'Mobiliser les notions apprises enrichit l’analyse de son propre travail.'],
  ['Si un camarade pose une question sur un choix précis du projet pendant la présentation, y répondre avec un exemple concret est-il utile ?','oui, un exemple concret clarifie souvent la réponse donnée',['non, il vaut toujours mieux rester vague face à une question précise','non, les questions des camarades n’ont jamais aucun intérêt','non, il faut toujours refuser de répondre aux questions posées'],'Répondre avec précision renforce la crédibilité de la présentation.'],
  ['Observer les présentations d’autres élèves peut-il aider à améliorer sa propre façon de présenter un projet ?','oui, observer différentes approches peut inspirer de nouvelles idées',['non, cela n’apporte jamais rien','non, il faut toujours ignorer totalement les présentations des autres','non, chaque présentation doit toujours être construite dans l’isolement complet'],'S’inspirer des pratiques d’autrui enrichit sa propre méthode.']]),2])}
]);

})();
